pub var gemma4_mtp_debug_override: bool = false;

pub const Message = struct {
    pub const ToolCall = jinja.ChatToolCall;
    pub const ContentPart = union(enum) {
        text: []const u8,
        image: usize,
        audio: usize,
    };

    role: []const u8,
    content: []const u8,
    content_is_null: bool = false,
    tool_calls: ?[]const ToolCall = null,
    tool_call_id: ?[]const u8 = null,
    /// Raw image bytes for multimodal messages (decoded from data URIs).
    /// Null or empty for text-only messages.
    image_bytes: ?[]const []const u8 = null,
    /// One video clip, sampled at one frame per second. CUDA takes H.264 MP4 up
    /// to 60s; CPU and Metal take the portable codecs, capped at 32 uniform frames.
    /// A request has one video, in its own message, with no image or audio parts.
    video_bytes: ?[]const u8 = null,
    /// Raw encoded audio bytes for multimodal messages.
    /// Null or empty for text/image-only messages.
    audio_bytes: ?[]const []const u8 = null,
    /// Trusted borrowed PCM, aligned with audio_bytes. Internal callers retain
    /// it until generation returns; public message parsing never supplies it.
    decoded_audio: ?[]const @import("audio.zig").PcmAudio = null,
    /// Optional structured content parts preserving text/image ordering.
    /// Image/audio parts store the index into `image_bytes`/`audio_bytes`.
    content_parts: ?[]const ContentPart = null,

    pub fn textBytes(self: Message) usize {
        var bytes = self.content.len;
        if (self.tool_call_id) |id| bytes +|= id.len;
        if (self.tool_calls) |calls| for (calls) |call| {
            bytes +|= call.id.len;
            bytes +|= call.type.len;
            bytes +|= call.name.len;
            bytes +|= call.arguments.len;
        };
        return bytes;
    }

    pub fn hasImages(self: Message) bool {
        if (self.video_bytes != null) return true;
        if (self.image_bytes) |imgs| return imgs.len > 0;
        return false;
    }

    pub fn hasAudio(self: Message) bool {
        if (self.audio_bytes) |clips| return clips.len > 0;
        return false;
    }
};

/// Check if any message in the batch contains images.
pub fn messagesHaveImages(messages: []const Message) bool {
    for (messages) |m| {
        if (m.hasImages()) return true;
    }
    return false;
}

/// Check if any message in the batch contains audio.
pub fn messagesHaveAudio(messages: []const Message) bool {
    for (messages) |m| {
        if (m.hasAudio()) return true;
    }
    return false;
}

/// Extra positions introduced when model-declared image placeholders expand.
/// Audio expansion is measured after projection because its token count varies
/// with the clip and projector metadata.
pub fn nativeGenerationMediaTokenAllowance(messages: []const Message, config: gpt_mod.Config) usize {
    var allowance = nativeGenerationImageTokenAllowance(messages, config);
    for (messages) |message| if (message.video_bytes != null) {
        allowance +|= gemma4_video.token_allowance;
    };
    return allowance;
}

test "dynamic image admission funds expanded rows without shortening the text window" {
    const images = [_][]const u8{ "first", "second" };
    const messages = [_]Message{.{ .role = "user", .content = "describe", .image_bytes = &images }};
    const config: gpt_mod.Config = .{ .family = .gemma, .gemma4_channel_protocol = true, .max_position_embeddings = 1024 };
    try std.testing.expectEqual(@as(usize, 562), nativeGenerationMediaTokenAllowance(&messages, config));
    try std.testing.expectEqual(@as(usize, 0), nativeGenerationPreliminaryMediaTokenAllowance(&messages, config));
    const admission = try nativeGenerationMediaAdmissionForBackend(std.testing.allocator, "", &messages, config, .generic, null);
    try std.testing.expectEqual(@as(usize, 585), try estimateNativeGenerationPromptTokenCount(23, admission.token_allowance, config, null, 32, 0));
    // The estimate is a reservation bound, not a rejection of a valid smaller
    // actual expansion close to the window. The expanded prompt is checked later.
    try std.testing.expectEqual(@as(usize, 992), try estimateNativeGenerationPromptTokenCount(900, admission.token_allowance, config, null, 32, 0));
    try std.testing.expectEqual(@as(usize, 0), nativeGenerationMediaTokenAllowance(&messages, .{ .family = .gemma }));
}

test "video prompt allowance is independent of the image token setting" {
    const messages = [_]Message{.{ .role = "user", .content = "describe", .video_bytes = "clip" }};
    try std.testing.expectEqual(@as(usize, 2848), nativeGenerationMediaTokenAllowance(&messages, .{ .family = .gemma }));
    try std.testing.expectEqual(@as(usize, 2848), nativeGenerationMediaTokenAllowance(&messages, .{ .family = .gemma, .mm_tokens_per_image = 280 }));
    try std.testing.expectEqual(@as(usize, 1120), try nativeGenerationPromptTokenLimit(.{ .family = .gemma, .max_position_embeddings = 4096 }, null, 128, 0, nativeGenerationMediaTokenAllowance(&messages, .{ .family = .gemma })));
    const short = [_]Message{.{ .role = "user", .content = "describe", .video_bytes = @embedFile("../testdata/video/h264-two-pps.mp4") }};
    const config = gpt_mod.Config{ .family = .gemma, .max_position_embeddings = 4096 };
    const actual = try nativeGenerationMediaAdmissionForBackend(std.testing.allocator, "", &short, config, .generic, null);
    try std.testing.expectEqual(@as(usize, 79), actual.token_allowance);
    const limit = try nativeGenerationPromptTokenLimit(config, null, 128, 0, nativeGenerationPreliminaryMediaTokenAllowance(&short, config));
    try std.testing.expectEqual(@as(usize, 1579), try estimateNativeGenerationPromptTokenCount(1500, actual.token_allowance, config, null, 128, 0));
    try std.testing.expectEqual(limit, try estimateNativeGenerationPromptTokenCount(limit - 1, actual.token_allowance, config, null, 128, 0));
    const rendered = try formatMessages(std.testing.allocator, &messages);
    defer std.testing.allocator.free(rendered);
    try std.testing.expect(std.mem.indexOf(u8, rendered, "<|video|> describe") != null);
}

pub const NativeGenerationMediaAdmission = struct {
    token_allowance: usize = 0,
    host_scratch_bytes: usize = 0,
    backend_scratch_bytes: usize = 0,
};

/// One source of truth for multimodal scheduler and process-wide admission.
/// Qwen3-VL probes encoded image headers and applies the exact smart-resize
/// geometry used by its projector; no image is decoded or projected here.
fn qwenVisionLimits(allocator: std.mem.Allocator, model_dir: []const u8, config: gpt_mod.Config) !qwen3vl_projector.Limits {
    if (config.family != .qwen3_5) return .{};
    const prep = try qwen2vl_mm.loadPreprocessorConfig(allocator, model_dir);
    if (prep.patch_size != config.vision_patch_size or prep.merge_size != config.vision_spatial_merge_size or
        prep.temporal_patch_size != config.vision_temporal_patch_size or
        prep.resample != .bicubic or
        !prep.do_resize or !prep.do_normalize or !prep.do_rescale or !prep.do_convert_rgb or
        !std.math.approxEqAbs(f32, prep.rescale_factor, 1.0 / 255.0, 1e-9) or
        !std.mem.eql(f32, &prep.image_mean, &.{ 0.5, 0.5, 0.5 }) or
        !std.mem.eql(f32, &prep.image_std, &.{ 0.5, 0.5, 0.5 })) return error.UnsupportedQwen2VlPreprocessorConfig;
    // Preserve the shared projector safety cap for high-resolution pages.
    const max_tokens = @min(try qwen2vl_mm.maxImageTokenCount(prep), 4096);
    const factor = @as(usize, prep.patch_size) * prep.merge_size;
    const min_tokens = @max(@as(usize, 4), @as(usize, prep.min_pixels) / (factor * factor));
    return .{ .min_merged_tokens = min_tokens, .max_merged_tokens = max_tokens, .hard_max_merged_tokens = max_tokens };
}

/// Cold optional pinned-input planning only. Reuses the exact resident CUDA
/// producer's resize geometry and prompt-limited vision policy. The caller may
/// precommit-decline this optimization on metadata failure; the ordinary image
/// validation/CPU preprocessing still executes once at its original boundary.
/// No image payload, SDK object, cache or quota is created here.
pub fn nativeCudaPinnedPatchUploadBytes(allocator: std.mem.Allocator, model_dir: []const u8, config: gpt_mod.Config, messages: []const Message, requested_output_tokens: usize) !usize {
    return nativeCudaPinnedPatchUploadBytesAtMost(allocator, model_dir, config, messages, requested_output_tokens, std.math.maxInt(usize));
}
pub fn nativeCudaPinnedPatchUploadBytesAtMost(allocator: std.mem.Allocator, model_dir: []const u8, config: gpt_mod.Config, messages: []const Message, requested_output_tokens: usize, maximum_upload_bytes: usize) !usize {
    if (!config.hasQwen35VisionArchitectureContract() or !messagesHaveImages(messages)) return 0;
    const images = try collectImagesInPromptOrder(allocator, messages);
    defer allocator.free(images);
    if (images.len == 0 or images.len > 8) return error.ImageLimitExceeded;
    const expanded_limit = try nativeGenerationPromptTokenLimit(config, null, requested_output_tokens, 0, 0);
    var limits = try qwenVisionLimits(allocator, model_dir, config);
    const per_image_budget = expanded_limit / images.len;
    if (per_image_budget < limits.min_merged_tokens) return error.InputTokenLimitExceeded;
    limits.max_merged_tokens = @min(limits.max_merged_tokens, per_image_budget);
    return qwen3vl_projector.planResidentCudaPatchUploadBytesAtMost(config, images, limits, maximum_upload_bytes);
}

/// Same prompt-limited singleton geometry as the ordinary numerical path.
/// Outside callers use the returned value only to request fresh optional quota.
pub fn nativeCudaVisionPublicationBytes(allocator: std.mem.Allocator, model_dir: []const u8, config: gpt_mod.Config, messages: []const Message, requested_output_tokens: usize, maximum_batch_items: usize) !usize {
    if (!config.hasQwen35VisionArchitectureContract() or !messagesHaveImages(messages)) return 0;
    const images = try collectImagesInPromptOrder(allocator, messages);
    defer allocator.free(images);
    if (images.len != 1) return 0;
    const expanded_limit = try nativeGenerationPromptTokenLimit(config, null, requested_output_tokens, 0, 0);
    var limits = try qwenVisionLimits(allocator, model_dir, config);
    if (expanded_limit < limits.min_merged_tokens) return error.InputTokenLimitExceeded;
    limits.max_merged_tokens = @min(limits.max_merged_tokens, expanded_limit);
    if (maximum_batch_items > 1) {
        const batch: ?qwen3vl_projector.ResidentBatchGeometry = qwen3vl_projector.residentBatchGeometry(.cuda, config, images[0], limits) catch |err| switch (err) {
            error.UnsupportedBatchedVision => null,
            else => return err,
        };
        if (batch) |shape| if (@min(maximum_batch_items, shape.max_items) > 1) return 0;
    }
    return qwen3vl_projector.planResidentFeaturePublicationBytes(config, images, limits);
}

pub fn prepareNativeVisionPublication(session: @import("../backends/session.zig").Session, primary: *runtime.tier.memory.AdmissionLease, bytes: usize, copies: usize, limits: runtime.tier.memory.Limits, control: InferenceExecutionControl) !(if (build_options.enable_cuda) ?@import("../execution/architecture_session.zig").PreparedComputeAdmission.SupplementalStorage else ?void) {
    if (comptime !build_options.enable_cuda) return null;
    if (comptime build_options.enable_cuda) {
        if (bytes == 0 or copies == 0 or copies > 2) return null;
        var requirements: [2]@import("../execution/prepared_storage_admission.zig").Requirement = undefined;
        for (requirements[0..copies]) |*entry| entry.* = .{ .backend = .cuda, .class = .activation, .bytes = bytes };
        const metadata = try std.math.mul(usize, copies, @sizeOf(ops.physical_storage.Lease) + 2 * @sizeOf(@import("../ops/cuda/cuda_compute.zig").CudaTensor) + 3 * @sizeOf(i64));
        const Supplement = @import("../execution/architecture_session.zig").PreparedComputeAdmission.SupplementalStorage;
        return Supplement.prepare(Supplement.requestSession(session, limits), primary, requirements[0..copies], .{ .consumer_metadata_bytes = metadata }, control);
    }
}

/// The fallback owner is selected only without an external projector or the
/// integrated Qwen3-VL architecture contract. Other media owners budget their
/// own routes; do not prepay this owner's credit for those paths.
pub fn fallbackImagePreparationBytes(config: gpt_mod.Config, projector_path: ?[]const u8, media: NativeGenerationMediaAdmission) usize {
    return if (projector_path == null and config.family == .qwen3_5 and !config.hasQwen35VisionArchitectureContract()) media.host_scratch_bytes else 0;
}

pub fn nativeGenerationMediaAdmission(
    allocator: std.mem.Allocator,
    model_dir: []const u8,
    messages: []const Message,
    config: gpt_mod.Config,
) !NativeGenerationMediaAdmission {
    return nativeGenerationMediaAdmissionForBackend(allocator, model_dir, messages, config, .generic, null);
}

pub fn nativeGenerationMediaAdmissionForBackend(
    allocator: std.mem.Allocator,
    model_dir: []const u8,
    messages: []const Message,
    config: gpt_mod.Config,
    backend: qwen3vl_projector.AdmissionBackend,
    projector_file: ?*const @import("../gguf/format.zig").File,
) !NativeGenerationMediaAdmission {
    return nativeGenerationMediaAdmissionControlled(allocator, model_dir, messages, config, backend, projector_file, .{});
}

pub fn nativeGenerationMediaAdmissionControlled(
    allocator: std.mem.Allocator,
    model_dir: []const u8,
    messages: []const Message,
    config: gpt_mod.Config,
    backend: qwen3vl_projector.AdmissionBackend,
    projector_file: ?*const @import("../gguf/format.zig").File,
    control: InferenceExecutionControl,
) !NativeGenerationMediaAdmission {
    return nativeGenerationMediaAdmissionWithInspection(allocator, model_dir, messages, config, backend, projector_file, control, null);
}

pub fn nativeGenerationMediaAdmissionWithInspection(
    allocator: std.mem.Allocator,
    model_dir: []const u8,
    messages: []const Message,
    config: gpt_mod.Config,
    backend: qwen3vl_projector.AdmissionBackend,
    projector_file: ?*const @import("../gguf/format.zig").File,
    control: InferenceExecutionControl,
    inspection: ?*@import("embedding_gemma2_video.zig").InspectionScope,
) !NativeGenerationMediaAdmission {
    try control.check();
    if (config.family == .qwen3_vl or config.hasQwen35VisionArchitectureContract()) {
        const images = try collectImagesInPromptOrder(allocator, messages);
        defer allocator.free(images);
        if (images.len == 0) return .{};
        const projector = try qwen3vl_projector.estimateAdmissionForBackend(images, config, try qwenVisionLimits(allocator, model_dir, config), backend);
        return .{
            // The text encode already contains an image placeholder. Retaining
            // one additional token per image preserves the existing
            // conservative allowance contract while the visual span itself is
            // exact.
            .token_allowance = std.math.add(usize, projector.visual_tokens, images.len) catch
                return error.PromptTooLong,
            .host_scratch_bytes = projector.host_scratch_bytes,
            .backend_scratch_bytes = projector.backend_scratch_bytes,
        };
    }
    if (config.family == .qwen3_5) {
        const image_count = nativeGenerationImageCount(messages);
        if (image_count == 0) return .{};
        const prep_config = try qwen2vl_mm.loadPreprocessorConfig(allocator, model_dir);
        const max_image_tokens = try qwen2vl_mm.maxImageTokenCount(prep_config);
        const images = try collectImagesInPromptOrder(allocator, messages);
        defer allocator.free(images);
        return .{ .token_allowance = image_count *| (max_image_tokens +| 1), .host_scratch_bytes = try qwen2vl_mm.imageWorkingBytes(images, prep_config) };
    }
    var admission: NativeGenerationMediaAdmission = .{ .token_allowance = nativeGenerationImageTokenAllowance(messages, config) };
    if (projector_file) |file| if (messagesHaveAudio(messages)) {
        const inputs = try collectAudioInPromptOrder(allocator, messages);
        defer allocator.free(inputs);
        admission.token_allowance = try std.math.add(usize, admission.token_allowance, try gemma4_projector.projectedAudioPromptTokenAllowance(file, inputs));
    };
    // CUDA decodes on the device. Portable decoding runs in host memory, and
    // CUDA's fallback to it admits that memory only when the fallback happens.
    for (messages) |message| if (message.video_bytes) |bytes| {
        // Malformed inputs retain the decoder's detailed diagnostic. The
        // scheduling estimate is permitted to be conservative in that case.
        admission.token_allowance +|= gemma4_video.promptAllowance(allocator, bytes, control, inspection) catch |err| switch (err) {
            error.OutOfMemory, error.VideoInputTooLarge, error.Cancelled, error.Canceled, error.Timeout, error.DeadlineExceeded => return err,
            else => gemma4_video.token_allowance,
        };
        if (backend == .cuda) continue;
        const reserved = try gemma4_video.reservationControlled(bytes, control);
        admission.host_scratch_bytes = reserved.host_bytes;
        admission.backend_scratch_bytes = reserved.surface_bytes;
    };
    return admission;
}

/// Conservative media-token count used for scheduling and memory admission.
/// Qwen image spans are dynamic, so derive their bound from the same
/// preprocessor configuration that produces the final visual tokens.
pub fn nativeGenerationAdmissionMediaTokenAllowance(
    allocator: std.mem.Allocator,
    model_dir: []const u8,
    messages: []const Message,
    config: gpt_mod.Config,
) !usize {
    return (try nativeGenerationMediaAdmission(allocator, model_dir, messages, config)).token_allowance;
}

/// Media allowance that can safely constrain the text-only encode before
/// dynamic image preprocessing determines the exact expanded prompt length.
pub fn nativeGenerationPreliminaryMediaTokenAllowance(messages: []const Message, config: gpt_mod.Config) usize {
    if (config.family == .qwen3_5 or config.family == .qwen3_vl or config.usesGemma4Channels()) return 0;
    return nativeGenerationImageTokenAllowance(messages, config);
}

fn nativeGenerationImageTokenAllowance(messages: []const Message, config: gpt_mod.Config) usize {
    const rows: usize = if (config.usesGemma4Channels()) gemma4_projector.default_max_image_tokens else config.mm_tokens_per_image;
    return if (rows == 0) 0 else nativeGenerationImageCount(messages) *| (rows +| 1);
}

fn nativeGenerationImageCount(messages: []const Message) usize {
    var image_count: usize = 0;
    for (messages) |message| {
        if (message.content_parts) |parts| {
            for (parts) |part| switch (part) {
                .image => image_count +|= 1,
                else => {},
            };
        } else if (message.image_bytes) |images| {
            image_count +|= images.len;
        }
    }
    return image_count;
}

/// Bound idle prefill chunks only for geometries with qualified measurements.
/// Keep the general scheduler ceiling intact for every other model and backend;
/// explicit request limits and memory admission are applied separately.
pub fn nativeGenerationPrefillChunkCeiling(
    backend: runtime.kv.pool.BackendKind,
    config: gpt_mod.Config,
    configured_ceiling: usize,
) usize {
    return nativeGenerationPrefillChunkCeilingPolicy(
        backend,
        config,
        configured_ceiling,
        platform.env.getenvBoolDefault("ANTFLY_GEMMA4_METAL_E4_PREFILL_CHUNK_2048", false),
        platform.env.getenvBoolDefault("ANTFLY_DISABLE_GEMMA4_METAL_E4_PREFILL_CHUNK_2048", false),
    );
}

fn nativeGenerationPrefillChunkCeilingPolicy(
    backend: runtime.kv.pool.BackendKind,
    config: gpt_mod.Config,
    configured_ceiling: usize,
    enable_e4_diagnostic: bool,
    disable_e4_diagnostic: bool,
) usize {
    const ceiling = @max(configured_ceiling, 1);
    if (backend == .cuda) {
        if (@import("../execution/gemma4_native_plan.zig").Plan.resolve(config)) |plan|
            return @min(ceiling, plan.geometry.prefillQueryLimit());
    }
    if (backend == .metal and
        config.family == .gemma and
        config.hasPle() and
        config.num_attention_heads == 8 and
        config.effectiveKVHeads() == 2 and
        config.headDim() == 256 and
        config.global_head_dim == 512 and
        config.sliding_window == 512 and
        !config.gemma4_mtp_assistant)
    {
        const exact_e4 = config.hidden_size == 2560 and
            config.num_hidden_layers == 42 and
            config.intermediate_size == 10240 and
            config.num_kv_shared_layers == 18;
        if (exact_e4 and enable_e4_diagnostic and !disable_e4_diagnostic) {
            return @min(ceiling, 2048);
        }
        return @min(ceiling, 512);
    }
    // Gemma4 E2B CUDA evidence currently selects the fixed 512-row schedule.
    // A forced 2051-row pass triggered a >2 GiB deferred-free drain, while
    // balanced 411-row and 513-row candidates were both slower. Keep the
    // fingerprint-specific winner until a new plan is promoted by paired E2E
    // evidence.
    if (backend == .cuda and
        config.family == .gemma and
        config.hidden_size == 1536 and
        config.num_hidden_layers == 35 and
        config.num_attention_heads == 8 and
        config.effectiveKVHeads() == 1 and
        config.headDim() == 256 and
        config.global_head_dim == 512 and
        config.intermediate_size == 6144 and
        config.shared_layer_intermediate_size == 12288 and
        config.num_kv_shared_layers == 20 and
        config.sliding_window == 512 and
        config.hasPle() and
        !config.gemma4_mtp_assistant)
    {
        return @min(ceiling, 512);
    }
    return ceiling;
}

/// Diagnostic telemetry only. Admission remains authoritative and callers log
/// only the chunk already selected and committed by the request budget.
pub fn traceNativeGenerationE4PrefillChunkAdmission(
    backend: runtime.kv.pool.BackendKind,
    config: gpt_mod.Config,
    prompt_tokens: usize,
    selected_chunk_rows: usize,
) void {
    if (backend != .metal or
        !platform.env.getenvBoolDefault("ANTFLY_GEMMA4_METAL_E4_PREFILL_CHUNK_2048", false) or
        platform.env.getenvBoolDefault("ANTFLY_DISABLE_GEMMA4_METAL_E4_PREFILL_CHUNK_2048", false) or
        config.family != .gemma or config.hidden_size != 2560 or config.num_hidden_layers != 42 or
        config.num_attention_heads != 8 or config.effectiveKVHeads() != 2 or config.headDim() != 256 or
        config.global_head_dim != 512 or config.intermediate_size != 10240 or
        config.num_kv_shared_layers != 18 or config.sliding_window != 512 or
        !config.hasPle() or config.gemma4_mtp_assistant) return;
    std.log.info("metal_e4_prefill_chunk2048_admission: selected_rows={d} prompt_tokens={d}", .{ selected_chunk_rows, prompt_tokens });
}

pub fn userFacingErrorMessage(err: anyerror) []const u8 {
    return switch (err) {
        error.AudioInputTooLong => "audio input is too long for the Gemma4 direct audio projector; trim the clip or raise clip.audio.max_tokens in the projector metadata",
        else => @errorName(err),
    };
}

pub const SpeculationPolicy = enum {
    auto,
    force,
    off,

    pub fn name(self: SpeculationPolicy) []const u8 {
        return switch (self) {
            .auto => "auto",
            .force => "force",
            .off => "off",
        };
    }
};

pub fn parseSpeculationPolicy(raw: []const u8) ?SpeculationPolicy {
    if (std.mem.eql(u8, raw, "auto")) return .auto;
    if (std.mem.eql(u8, raw, "force")) return .force;
    if (std.mem.eql(u8, raw, "off")) return .off;
    return null;
}

pub const SpeculationCalibration = enum {
    none,
    probe,
    positive,

    pub fn name(self: SpeculationCalibration) []const u8 {
        return switch (self) {
            .none => "none",
            .probe => "probe",
            .positive => "positive",
        };
    }
};

pub fn parseSpeculationCalibration(raw: []const u8) ?SpeculationCalibration {
    if (std.mem.eql(u8, raw, "none") or std.mem.eql(u8, raw, "off")) return .none;
    if (std.mem.eql(u8, raw, "probe") or std.mem.eql(u8, raw, "calibrate")) return .probe;
    if (std.mem.eql(u8, raw, "positive") or std.mem.eql(u8, raw, "calibrated")) return .positive;
    return null;
}

