                .disabled, .compiled_bypass => {},
                .reject => return error.UnqualifiedCompactionArtifact,
                .prepare => |maximum_rows| {
                    const compute = checkpoint_compute orelse return error.UnqualifiedCompactionArtifact;
                    const admission = self.e2b_f16_mirror_admission orelse return error.CompactionWorkspaceLimit;
                    var execution_scope = if (self.execution_lock) |mutex| try self.lockExecution(mutex) else null;
                    defer if (execution_scope) |*scope| scope.deinit();
                    try compute.prepareAuthenticatedResidentFfnSlots(self.gpt_config, admission, grant.checkpoint_identity, maximum_rows);
                    try compute.activateAuthenticatedResidentFfnIdentity(self.attention_match_identity orelse return error.UnsupportedKvIdentity);
                },
            }
        }
        try setWorkloadProfileRegime(&self.cb, .prefill);
        try self.logMetalCheckpointQualificationPhase(decode_state, config, "prefill_started", null);
        const quality_requested = if (comptime builtin.is_test) config.context_quality_request != null else false;
        // Checkpoint preparation and teacher-forced qualification consume the
        // owned final logit row; neither may take the token-only shortcut.
        const allow_prefill_greedy_token = self.checkpoint_prepare == null and !quality_requested and
            (!use_speculative or draft_is_gemma4_mtp);
        const capture_mtp_prefill_hidden = use_speculative and draft_is_gemma4_mtp and gemma4MtpTargetHiddenSource() == .final;
        if (self.usesPjrtSession()) {
            if (prepared_qwen3vl_prompt) |*prepared| {
                if (prepared.deepstack_layer_count != 0) return error.UnsupportedResidentQwenVision;
                compiled_prefix = try self.compileMediaPrefix(prepared.input_embeddings orelse return error.InvalidPreparedPrompt, prepared.token_ids.len, null, prepared.plan.mrope_positions, prepared.plan.mrope_position_delta, null);
            } else if (prepared_multimodal_prompt) |*prepared| {
                compiled_prefix = try self.compileMediaPrefix(prepared.input_embeddings orelse return error.InvalidPreparedPrompt, prepared.token_ids.len, prepared.ple_token_ids, null, 0, prepared.attn_or_mask);
            }
            if (compiled_prefix) |*prefix| self.compiled_media_prefix = prefix;
        }
        if (self.usesPjrtSession()) {
            const capacity = @min(try std.math.add(usize, seq_len, max_tokens), self.gpt_config.max_position_embeddings);
            const resident_decoder = @import("../execution/resident_decoder.zig");
            const cache_candidate = try resident_decoder.select(self.session.?, self.pjrt_decoder_cache);
            const whole_prefill = if (cache_candidate) whole: {
                break :whole if (compiled_prefix) |*prefix| try prefix.cachedAdmission(seq_len, self.gpt_config.max_position_embeddings) else null;
            } else null;
            compiled_decoder = try resident_decoder.Decoder.initForRequest(self.allocator, self.session.?, self.pjrt_decoder_cache, .{ .limit = capacity, .prompt_rows = seq_len, .max_tokens = max_tokens, .query_rows = config.prefill_chunk_size, .whole_prefill = whole_prefill }, self.execution_control);
            if (compiled_decoder == null and config.prefill_chunk_size != 0) {
                if (compiled_prefix) |*prefix| {
                    if (try prefix.ordinaryRows(seq_len, self.session.?) > config.prefill_chunk_size) return error.UnsupportedCompiledMediaPrefillChunking;
                }
            }
            if (compiled_decoder) |*decoder| {
                self.compiled_decoder = decoder;
                self.pjrt_decoder_cache_used = true;
            }
        }
        const prefill_output = if (self.compiled_decoder) |decoder|
            PrefillOutput{ .last_logits = if (self.compiled_media_prefix) |prefix| try prefix.runCached(decoder, token_ids[0..seq_len], allocator, self.execution_control) else try decoder.text(token_ids[0..seq_len], allocator, self.execution_control) }
        else if (self.compiled_media_prefix) |prefix|
            PrefillOutput{ .last_logits = try prefix.run(self.session.?, token_ids[0..seq_len], allocator, self.execution_control) }
        else if (self.checkpoint_resume) |request|
            try self.resumeNativeCheckpoint(request, token_ids[0..seq_len], max_tokens, decode_state, config)
        else if (prepared_qwen3vl_prompt) |*prepared|
            try self.executePreparedQwen3VlPrefill(prepared, seq_len, decode_state, shouldUsePreparedQwenPrefillGreedyToken(
                self.cb.kind(),
                self.gpt_config,
                config,
                allow_prefill_greedy_token and !use_speculative and !has_any_grammar,
                self.prefillNeedsHostLogits(config),
                enableCudaPrefillFirstToken() and enableCudaPrefillGreedyToken(),
            ))
        else if (prepared_multimodal_prompt) |*prepared|
            try self.executePreparedMultimodalPrefill(prepared, seq_len, decode_state, capture_mtp_prefill_hidden, config)
        else
            self.executePrefill(prefill_ids, seq_len, cached_prompt_tokens, decode_state, config, allow_prefill_greedy_token, capture_mtp_prefill_hidden, false) catch |err| {
                if (comptime builtin.is_test) if (config.context_fault_controller) |fault| {
                    const observed = fault.snapshot();
                    const completed: usize = observed.completed_units;
                    if (observed.injected and observed.kind == .cancel_prefill and
                        completed > 0 and completed <= token_ids.len and
                        owned_packed != null)
                    {
                        const prefix = token_ids[0..completed];
                        decode_state.last_context_fault_partial = owned_packed.?.failureFingerprint(contextFaultTokenDigest(prefix)) catch null;
                    }
                };
                return err;
            };
        if (self.compiled_decoder) |decoder| {
            self.resident_prefill_steps = decoder.prefill_steps;
            self.resident_prefill_head_skips = decoder.prefill_head_skips;
        }
        if (native_work_enabled) {
            std.debug.print("native_work_prefill_complete: pipeline={d} source_tokens={d} cached_prefix={d} declared_query_tokens={d}\n", .{ @intFromPtr(self), seq_len, cached_prompt_tokens, prefill_ids.len });
        }
        if (self.checkpoint_resume) |request| cached_prompt_tokens = request.restored_tokens;
        var prefill_last_logits = prefill_output.last_logits;
        var prefill_greedy_token = prefill_output.greedy_token;
        const prefill_last_hidden = prefill_output.last_hidden;
        const prefill_last_hidden_rows = prefill_output.last_hidden_rows;
        defer if (prefill_last_logits) |logits| allocator.free(logits);
        defer if (prefill_last_hidden) |hidden| self.cb.free(hidden);
        if (config.compiled_packed_prefill_bridge != null) {
            const packed_config = deferred_compiled_packed_config orelse return error.InvalidCompiledExactImportState;
            owned_packed = try @import("../backends/packed_context_session.zig").Session.init(allocator, packed_config);
            const allocation = owned_packed.?.ownerAllocationStart();
            decode_state.last_context_session_allocation_start = allocation.allocation;
            decode_state.last_context_session_allocation_exclusive = allocation.session_scope_exclusive;
            decode_state.last_context_full_owner_physical_available = allocation.full_owner_physical_available;
            const live = if (owned_packed) |*session| session else return error.InvalidCompiledExactImportState;
            try self.bridgeCompiledPrefillIntoPacked(live, token_ids[0..seq_len], config);
            compiled_packed_runtime_cleanup.handoffComplete();
            decode_state.context_session = live.hook();
            if (config.metal_checkpoint_packed_singleton_evidence_sink) |sink| sink.* = live.singletonDecodeSealEvidence();
        }
        if (config.native_checkpoint_operator_grant) |grant| {
            if (grant.authority_kind == .staged_exact_baseline and grant.arm == .optimal_compiled_exact) {
                if (self.qualification_matrix_compiled_source_authority != null) return error.InvalidExactPagedKvHandoffState;
                const cache = self.graph_cache orelse return error.MissingCompiledModelRuntime;
                self.qualification_matrix_compiled_source_authority = try graph_mod.execution.compiledModelExactPagedKvAuthority(self, cache);
            }
            if (grant.authority_kind == .staged_exact_baseline and grant.arm == .packed_exact and
                config.context_storage == .packed_exact and config.compiled_packed_prefill_bridge == null)
            {
                const live = if (owned_packed) |*session| session else return error.UnqualifiedCompactionArtifact;
                try live.sealForSingletonDecode();
                if (config.metal_checkpoint_packed_singleton_evidence_sink) |sink| sink.* = live.singletonDecodeSealEvidence();
            }
        }
        if (self.bounded_ple_prefill_decode_handoff_required) {
            const cache = self.graph_cache orelse return error.RequiredCompiledRuntimePrepareDeclined;
            if (!try graph_mod.execution.finishCompiledModelPrefillForDecode(self, cache))
                return error.RequiredCompiledRuntimePrepareDeclined;
            self.bounded_ple_prefill_decode_handoff_required = false;
        }
        const finished_prefill_at = if (self.io) |io| std.Io.Timestamp.now(io, .awake) else std.Io.Timestamp.zero;
        if (self.prefill_logits_out) |dest| {
            const row = prefill_last_logits orelse return error.MissingLogitCapture;
            if (dest.len != self.gpt_config.vocab_size or dest.len != row.len) return error.InvalidLogitCapture;
            @memcpy(dest, row);
        }
        if (config.qwen3vl_parity_logits_path) |path| {
            if (prepared_qwen3vl_prompt == null or prefill_last_logits == null or
                prefill_last_logits.?.len != self.gpt_config.vocab_size)
            {
                return error.MissingQwen3VlPrefillLogits;
            }
            try writeF32LeFile(allocator, self.io orelse return error.MissingIo, path, prefill_last_logits.?);
        }
        debugGenerationStage(
            "finished prefill seq_len={d} cached_logits={} greedy_token={}",
            .{ seq_len, prefill_last_logits != null, prefill_greedy_token != null },
        );
        packed_profile_after_prefill = if (packed_grant_profile) packedGrantProfileSnapshot(self) else null;

        if (self.checkpoint_prepare) |request| {
            if (request.qualification_phase_telemetry) |*owned| {
                const now = platform.time.monotonicNs();
                try owned.observer().emit(.source_prefill, .end, now);
                try owned.observer().emit(.compiled_handoff, .begin, now);
            }
            try self.handoffPrivateCompiledPrefill(request, token_ids[0..seq_len], decode_state, config);
            try self.prepareNativeCheckpoint(request, token_ids[0..seq_len], prefill_last_logits orelse return error.MissingCompactionResumeLogits, decode_state, config);
            // This is preparation wall time through fitting, not end-to-end TTFT.
            // Export, upload, install, and first-content delivery remain measured by
            // the outer SDK request timer.
            if (request.compiled_prefill_preparation_wall_started_at) |preparation_started_at|
                request.compiled_prefill_preparation_wall_ns = mtpProfileElapsedNs(true, self.io, preparation_started_at);
            try self.logNativeCheckpointRequestPrivatePublish(decode_state, config, request);
            if (config.metal_native_checkpoint_qualification and
                config.metal_checkpoint_qualification_route != .none and
                self.cb.kind() == .metal)
            {
                if (decode_state.total_tokens != seq_len) return error.InvalidKvCheckpoint;
                // Preparation ends immediately after a complete prefill:
                // every logical prompt token already owns a materialized
                // KV row, and no sampled decode token is pending.
                self.metal_qualification_completion = try metalQualificationCompletion(
                    seq_len,
                    decode_state.total_tokens,
                    0,
                );
            }
            return .{
                .text = try allocator.dupe(u8, ""),
                .prompt_tokens = seq_len,
                .tokens_used = 0,
                .finish_reason = "stop",
                .allocator = allocator,
            };
        }

        if (serving_compaction) |request| {
            const live = if (owned_packed) |*session| session else return error.InvalidContextTransaction;
            if (comptime builtin.is_test) {
                if (config.context_fault_controller != null)
                    decode_state.last_context_fault_before = try live.failureFingerprint(request.sources.question.prompt_tokens_sha256);
            }
            request.run(live, self.compactionCampaignRunnerWithFault(config.context_fault_controller)) catch |err| {
                if (comptime builtin.is_test) {
                    if (config.context_fault_controller != null)
                        decode_state.last_context_fault_after = live.failureFingerprint(request.sources.question.prompt_tokens_sha256) catch null;
                }
                return err;
            };
        } else if (coordinated_request) |*request| {
            if (comptime !builtin.is_test or !@import("build_options").enable_metal)
                return error.UnqualifiedCompactionArtifact;
            const live = if (owned_packed) |*session| session else return error.InvalidContextTransaction;
            try request.run(live, self, runCompactionReplay, qualification.?.publish);
        }

        var quality_generation_evidence: if (builtin.is_test) ?context_teacher_forced.Evidence else void = if (builtin.is_test) null else {};
        if (comptime builtin.is_test) if (config.context_quality_request) |quality| {
            var rendered_prompt_sha256: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(prompt, &rendered_prompt_sha256, .{});
            if (quality.loaded_generation != self.load_generation or quality.reference_token_count < context_teacher_forced.min_reference_tokens or
                quality.reference_token_count > context_teacher_forced.max_reference_tokens or
                !std.mem.eql(u8, &quality.rendered_prompt_sha256, &rendered_prompt_sha256) or
                @as(usize, quality.reference_token_count) > token_ids.len - seq_len)
                return error.InvalidTeacherForcedRequest;
            const prompt_tokens_sha256 = try context_teacher_forced.promptTokenDigest(token_ids[0..seq_len]);
            const fingerprint = switch (quality.variant) {
                .exact => blk: {
                    const layout = try runtime.context_policy.Layout.init(self.gpt_config);
                    if (layout.len != self.gpt_config.num_hidden_layers) return error.InvalidQualificationFingerprint;
                    break :blk try decode_state.qualificationOrdinaryExactFingerprint(allocator, seq_len, layout);
                },
                .attention_matching => blk: {
                    const live = if (owned_packed) |*session| session else return error.InvalidTeacherForcedContext;
                    if (!decode_state.hasRetainedAttention()) return error.InvalidTeacherForcedContext;
                    break :blk try live.qualificationFingerprint();
                },
            };
            const binding = context_teacher_forced.ContextBinding{
                .variant = quality.variant,
                .context_instance_id = fingerprint.context_instance_id,
                .publication_epoch = fingerprint.publication_epoch,
                .context_logical_tokens = fingerprint.logical_tokens,
                .prompt_tokens = std.math.cast(u32, seq_len) orelse return error.InvalidTeacherForcedRequest,
                .rendered_prompt_sha256 = rendered_prompt_sha256,
                .prompt_tokens_sha256 = prompt_tokens_sha256,
                .reference_token_count = quality.reference_token_count,
                .reference_sequence_sha256 = quality.reference_sequence_sha256,
                .loaded_generation = self.load_generation,
                .profile_artifact_sha256 = quality.profile_artifact_sha256,
                .profile_semantic_sha256 = quality.profile_semantic_sha256,
                .implementation_sha256 = quality.implementation_sha256,
                .published_payload_sha256 = fingerprint.payload_sha256,
                .published_descriptor_sha256 = fingerprint.descriptor_sha256,
                .diagnostic_kv_readback_bytes = fingerprint.diagnostic_kv_readback_bytes,
            };
            if (quality.mode == .teacher) {
                const logits = prefill_last_logits orelse return error.MissingTeacherForcedPrefillLogits;
                const reference = try context_teacher_forced.revealVerifiedReference(quality, binding);
                var receipt = try self.scoreTeacherForcedContinuation(token_ids, &seq_len, decode_state, logits, reference, binding);
                var receipt_owned = true;
                errdefer if (receipt_owned) receipt.deinit();
                prefill_last_logits = null;
                allocator.free(logits);
                const empty_text = try allocator.alloc(u8, 0);
                errdefer allocator.free(empty_text);
                const empty_ids = try allocator.alloc(i32, 0);
                receipt_owned = false;
                return .{
                    .text = empty_text,
                    .token_ids = empty_ids,
                    .prompt_tokens = prompt_token_count,
                    .tokens_used = reference.len,
                    .finish_reason = "teacher_forced",
                    .cached_prompt_tokens = cached_prompt_tokens,
                    .teacher_forced_evidence = .{ .teacher = receipt },
                    .allocator = allocator,
                };
            }
            quality_generation_evidence = .{ .generation = binding };
            self.last_quality_generation_binding = binding;
        };
        const finished_maintenance_at = if (self.io) |io| std.Io.Timestamp.now(io, .awake) else std.Io.Timestamp.zero;

        if (platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_REFERENCE_PROBE")) {
            if (prepared_multimodal_prompt != null or prepared_qwen3vl_prompt != null or use_speculative or
                config.kv_cache_mode == .select_v1 or config.cache_compaction_ratio != null or decode_state.isKvCompacted())
                return error.UnsupportedCompactionQueryRoute;
            const started = mtpProfileTimestamp(true, self.io);
            const original_tokens = decode_state.total_tokens;
            const original_sequence = decode_state.sequence_id;
            const prefix_mode = platform.env.getenv("ANTFLY_INFERENCE_ATTENTION_MATCH_PREFIX_MODE") orelse "clone";
            if (!std.mem.eql(u8, prefix_mode, "clone") and !std.mem.eql(u8, prefix_mode, "replay")) return error.UnsupportedCompactionQueryRoute;
            const repeat_mode_name = platform.env.getenv("ANTFLY_INFERENCE_ATTENTION_MATCH_REPEAT_MODE") orelse "reference";
            const repeat_mode: @FieldType(AttentionMatchQueryOptions, "repeat_mode") = if (std.mem.eql(u8, repeat_mode_name, "reference")) .reference else if (std.mem.eql(u8, repeat_mode_name, "exact")) .exact else if (std.mem.eql(u8, repeat_mode_name, "exact_split")) .exact_split else return error.UnsupportedCompactionQueryRoute;
            const query_samples = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_QUERY_SAMPLES") orelse 80;
            const repeat_chunk_size = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_REPEAT_CHUNK_SIZE") orelse 256;
            const suffix_limit = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_REFERENCE_SUFFIX_TOKENS") orelse 0;
            const max_repeat_tokens: ?usize = if (suffix_limit == 0) null else suffix_limit;
            const representative_repeat = platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_FIT_NATIVE_POLICY");
            if (query_samples < 2 or query_samples > 320 or (repeat_chunk_size != 256 and repeat_chunk_size != 512)) return error.CompactionQueryLimit;
            var query_stats = AttentionMatchQueryStats{};
            var queries = try self.collectAttentionMatchQueries(token_ids[0..seq_len], decode_state, .{
                .prefix_mode = if (std.mem.eql(u8, prefix_mode, "clone")) .clone else .replay,
                .stats = &query_stats,
                .repeat_mode = repeat_mode,
                .collection = .{ .samples_per_consumer = query_samples },
                .chunk_size = repeat_chunk_size,
                .max_repeat_tokens = max_repeat_tokens,
                .representative_repeat = representative_repeat,
            });
            defer queries.deinit();
            const query_elapsed_ns = mtpProfileElapsedNs(true, self.io, started);
            const verify_clone = platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_VERIFY_CLONE");
            var reference_ns: u64 = 0;
            if (verify_clone) {
                if (!std.mem.eql(u8, prefix_mode, "clone")) return error.UnsupportedCompactionQueryRoute;
                const reference_started = mtpProfileTimestamp(true, self.io);
                var reference = try self.collectAttentionMatchQueries(token_ids[0..seq_len], decode_state, .{ .prefix_mode = .replay, .repeat_mode = repeat_mode, .collection = .{ .samples_per_consumer = query_samples }, .chunk_size = repeat_chunk_size, .max_repeat_tokens = max_repeat_tokens, .representative_repeat = representative_repeat });
                defer reference.deinit();
                reference_ns = mtpProfileElapsedNs(true, self.io, reference_started);
                if (!std.mem.eql(u64, queries.train_positions, reference.train_positions) or
                    !std.mem.eql(u64, queries.heldout_positions, reference.heldout_positions) or
                    !std.mem.eql(u8, std.mem.sliceAsBytes(queries.values), std.mem.sliceAsBytes(reference.values)))
                    return error.CompactionCloneQueryMismatch;
            }
            const verify_repeat = platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_VERIFY_REPEAT");
            var agreement = runtime.kv.attention_match_queries.Agreement{};
            if (verify_repeat) {
                if (repeat_mode == .reference) return error.UnsupportedCompactionQueryRoute;
                const reference_started = mtpProfileTimestamp(true, self.io);
                var reference = try self.collectAttentionMatchQueries(token_ids[0..seq_len], decode_state, .{ .collection = .{ .samples_per_consumer = query_samples }, .chunk_size = repeat_chunk_size, .max_repeat_tokens = max_repeat_tokens, .representative_repeat = representative_repeat });
                reference_ns += mtpProfileElapsedNs(true, self.io, reference_started);
                defer reference.deinit();
                agreement = try queries.compare(&reference);
                // Every sampled query must preserve the established FP32 path.
                // This is not a fitted-cache quality gate.
                if (!std.mem.eql(u8, std.mem.sliceAsBytes(queries.values), std.mem.sliceAsBytes(reference.values))) {
                    std.log.err("attention_match_repeat_rejected max_absolute={d} max_relative_l2={d}", .{ agreement.max_absolute, agreement.max_relative_l2 });
                    var value_offset: usize = 0;
                    for (queries.consumers) |consumer| {
                        const values = consumer.query_heads * consumer.dim * queries.samples.len;
                        const row = try runtime.kv.attention_match_queries.compareRows(queries.values[value_offset..][0..values], reference.values[value_offset..][0..values], consumer.dim);
                        std.log.err("attention_match_repeat_consumer layer={d} max_absolute={d} max_relative_l2={d}", .{ consumer.layer, row.max_absolute, row.max_relative_l2 });
                        value_offset += values;
                    }
                    return error.CompactionRepeatQueryMismatch;
                }
            }
            if (decode_state.total_tokens != original_tokens or decode_state.sequence_id != original_sequence)
                return error.CompactionSourceChanged;
            var query_hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(std.mem.sliceAsBytes(queries.values), &query_hash, .{});
            std.log.info("attention_match_queries source_tokens={d} consumers={d} heads={d} train={d} heldout={d} host_query_peak_bytes={d} elapsed_ns={d} prefix_ns={d} repeat_ns={d} cloned_bytes={d} shadow_allocation_bound_bytes={d} verified_clone={d} reference_ns={d} prefix_mode={s} query_sha256={s} repeat_mode={s} verified_repeat={d} query_max_absolute={d} query_max_relative_l2={d} repeat_kernel_launches={d} split_kernel_launches={d} scratch_bytes={d} setup_ns={d} cleanup_ns={d} chunk_size={d} reference_tokens={d} ragged_repeat_calls={d}", .{
                seq_len,                           queries.consumers.len,     queries.batches.len,                       queries.train_positions.len,
                queries.heldout_positions.len,     queries.peak_bytes,        query_elapsed_ns,                          query_stats.prefix_ns,
                query_stats.repeat_ns,             query_stats.cloned_bytes,  query_stats.shadow_allocation_bound_bytes, @intFromBool(verify_clone),
                reference_ns,                      prefix_mode,               std.fmt.bytesToHex(query_hash, .lower),    repeat_mode_name,
                @intFromBool(verify_repeat),       agreement.max_absolute,    agreement.max_relative_l2,                 query_stats.repeat_kernel_launches,
                query_stats.split_kernel_launches, query_stats.scratch_bytes, query_stats.setup_ns,                      query_stats.cleanup_ns,
                repeat_chunk_size,                 queries.repeat_length,     query_stats.ragged_repeat_calls,
            });
            const cycles = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_CYCLES") orelse 0;
            if (cycles != 0) {
                const append_tokens = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_CYCLE_APPEND") orelse 1024;
                const answer_tokens = platform.env.getenvUsize("ANTFLY_INFERENCE_ATTENTION_MATCH_CYCLE_ANSWER") orelse 16;
                const minimum_savings = try std.fmt.parseFloat(f64, platform.env.getenv("ANTFLY_INFERENCE_ATTENTION_MATCH_CYCLE_MIN_SAVINGS") orelse "1.000001");
                try self.probeAttentionMatchCycles(token_ids[0..seq_len], prefill_last_logits orelse return error.MissingCompactionResumeLogits, decode_state, cycles, append_tokens, answer_tokens, minimum_savings);
            }
            if (platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_FIT_PROBE"))
                _ = try self.probeAttentionMatchFit(token_ids[0..seq_len], prefill_last_logits orelse return error.MissingCompactionResumeLogits, decode_state, &queries, query_elapsed_ns, .{});
            if (platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_VERIFY_RESTORE"))
                try self.verifyRestoredAttentionMatch(token_ids[0..seq_len], prefill_last_logits orelse return error.MissingCompactionResumeLogits, decode_state);
        }

        {
            var cache_scope = if (self.prompt_cache != null) if (self.execution_lock) |mutex| try self.lockExecution(mutex) else null else null;
            defer if (cache_scope) |*scope| scope.deinit();
            decoder_storage.storePromptPrefix(&self.cb, prefix_binding, decode_state, self.prompt_cache, prefix_request, token_ids[0..seq_len]);
        }

        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| {
                scheduler.beginDecode(lease, seq_len);
            }
        }

        // Compact KV cache after prefill if configured.
        if (config.cache_compaction_ratio) |ratio| {
            if (NativeDecodeState.requiresDeepSeekV4CompressedCache(self.gpt_config)) {
                return error.DeepSeekV4CompressedKvCompactionNotSupported;
            }
            var decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);
            try decode_runtime.compactKvCache(.{ .target_ratio = ratio });
        }

        var finish_reason: []const u8 = "length";
        var tokens_generated: usize = 0;
        var pending_unmaterialized_tokens: u8 = 0;
        var speculative_stats = SpeculativeDecodeStats{};
        speculative_stats.prompt_lookup_requested = prompt_lookup_requested;
        speculative_stats.speculation_policy = speculation_policy;
        speculative_stats.speculation_calibration = config.speculation_calibration;
        speculative_stats.mtp_graph_replay_status = gemma4MtpGraphReplayStatusName();
        speculative_stats.mtp_profile.enabled = gemma4MtpProfileEnabled();
        speculative_stats.mtp_profile.sync_enabled = gemma4MtpProfileSyncEnabled();
        if (draft_requested) {
            speculative_stats.mtp_enabled = use_speculative and draft_is_gemma4_mtp;
            speculative_stats.speculation_policy_decision = if (speculation_policy == .off)
                .disabled_off
            else if (mtp_auto_uncalibrated)
                .disabled_uncalibrated
            else if (!use_speculative)
                .disabled_unavailable
            else if (speculation_policy == .force)
                .forced
            else
                .active;
            if (disable_unshared_gemma4_mtp) {
                speculative_stats.mtp_disabled_reason = "target_missing_shared_kv_metadata";
            } else if (speculation_policy == .off) {
                speculative_stats.mtp_disabled_reason = "speculation_policy_off";
            } else if (mtp_auto_uncalibrated) {
                speculative_stats.mtp_disabled_reason = "speculation_calibration_required";
            } else if (mtp_auto_too_short) {
                speculative_stats.mtp_disabled_reason = "mtp_auto_min_tokens";
            } else if (mtp_metal_auto_disabled) {
                speculative_stats.mtp_disabled_reason = "metal_mtp_auto_disabled";
            } else if (target_speculative_verification_unavailable) {
                speculative_stats.mtp_disabled_reason = "a4b_metal_speculative_verify_unqualified";
            }
        }
        const stream_enabled = on_token_fn != null and on_token_ctx != null;
        const final_channel_required = self.gpt_config.usesGemma4Channels();
        // Resolve the channel protocol once for the whole request. Buffered and
        // streaming callers must use the same exact final-header projection;
        // resolving only the generic terminator at completion can expose a
        // malformed trailing private channel.
        const final_channel_end = if (final_channel_required)
            try self.resolveFinalChannelEndTokenId()
        else
            null;
        const turn_end = if (final_channel_end != null)
            try self.resolveTurnEndTokenId()
        else
            null;
        const channel_start = if (final_channel_end != null)
            try self.resolveChannelStartTokenId()
        else
            null;
        const owned_final_channel_header = if (final_channel_end) |marker|
            try self.resolveFinalChannelHeaderTokenIds(marker)
        else
            null;
        defer if (owned_final_channel_header) |ids| allocator.free(ids);
        const owned_thought_header = if (canonical_prompt != null and channel_start != null and final_channel_end != null and turn_end != null)
            try self.tokenizer.encode(allocator, "<|channel>thought\n")
        else
            null;
        defer if (owned_thought_header) |ids| allocator.free(ids);
        var streaming_text = StreamingTextState{
            .token_table = if (token_table) |*table| table else null,
            .emitted_text = if (stream_enabled) try allocator.dupe(u8, "") else &.{},
            .canonical = if (owned_thought_header) |header|
                if (header.len > 1 and header[0] == channel_start.?)
                    Gemma4Projection.init(canonical_prompt.?, channel_start.?, final_channel_end.?, turn_end.?, header)
                else
                    null
            else
                null,
            .final_channel_required = final_channel_required,
            .final_channel_preopened = prompt_opens_public_final_channel,
            .final_channel_end_token_id = final_channel_end,
            .final_channel_header_token_ids = owned_final_channel_header orelse &.{},
            .channel_start_token_id = channel_start,
            .turn_end_token_id = turn_end,
            .final_channel_content_start = if (prompt_opens_public_final_channel) 0 else null,
            .saw_final_channel = prompt_opens_public_final_channel,
        };
        defer if (stream_enabled) allocator.free(streaming_text.emitted_text);
        var penalty_state = SamplingPenaltyState.init(hasSamplingPenalties(config));
        defer penalty_state.deinit(allocator);
        try penalty_state.seedFromHistory(allocator, token_ids[0..seq_len]);

        // Pending token readback consumes the prefill result itself, keeps the
        // token resident, and resolves EOS before submitting the next graph.
        // Do not materialize the first
        // token through the ordinary prefill shortcut first: doing so advances
        // `tokens_generated` to one and permanently bypasses the pipelined
        // path for the rest of the request.
        const use_cuda_pending_token_readback = shouldUseCudaPendingTokenReadback(
            self.cb.kind(),
            enableCudaGreedyPendingTokenReadback(),
            isPureGreedyConfig(config),
            use_speculative,
            has_any_grammar,
            self.graph_cache != null or self.compiled_partition_backend != null,
            self.execution_lock != null,
            max_tokens,
        );
        var prefill_decode_complete = false;
        if (!use_speculative and !use_cuda_pending_token_readback) {
            if (try self.tryReturnPrefillFirstToken(
                token_ids,
                &seq_len,
                config,
                &prefill_last_logits,
                &prefill_greedy_token,
                &penalty_state,
                if (token_table) |*tt| tt else null,
                &json_grammar,
                if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                max_tokens,
                prompt_token_count,
                if (stream_enabled) on_token_fn else null,
                if (stream_enabled) on_token_ctx else null,
                if (stream_enabled) &streaming_text else null,
                native_work_enabled,
            )) |decode_result| {
                tokens_generated = decode_result.tokens_generated;
                finish_reason = decode_result.finish_reason;
                pending_unmaterialized_tokens = decode_result.pending_unmaterialized_tokens;
                prefill_decode_complete = tokens_generated >= max_tokens or std.mem.eql(u8, finish_reason, "stop");
                if (!prefill_decode_complete and tokens_generated > 0) {
                    // The first token came from the prompt's final row. Clear
                    // that one-shot output before entering decode so it cannot
                    // be sampled twice, then advance the paged state exactly
                    // as standardDecode would after accepting the token.
                    if (prefill_last_logits) |logits| {
                        allocator.free(logits);
                        prefill_last_logits = null;
                    }
                    prefill_greedy_token = null;
                    var continued_decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);
                    const kv_mutation_mutex = batchKvMutationMutex(self.execution_lock, decode_state.kv_lock);
                    var execution_scope = if (kv_mutation_mutex) |mutex| try self.lockKvMetadata(mutex) else null;
                    defer if (execution_scope) |*scope| scope.deinit();
                    _ = try continued_decode_runtime.appendGeneratedToken();
                }
            }
        }

        if (use_speculative) {
            const draft_cb = self.draft_cb.?;
            const draft_gpt_config = self.draft_gpt_config.?;
            const use_gemma4_mtp = draft_gpt_config.gemma4_mtp_assistant;
            const mtp_hidden_source = gemma4MtpTargetHiddenSource();

            // Create a temporary draft pipeline (borrows self's allocator/tokenizer)
            var draft_fallback_state = NativeDecodeState.initContiguous(allocator);
            defer if (self.draft_execution_cleanup_owner) |owner| {
                draft_fallback_state.deinitWithCleanup(.{ .boundary = owner.epoch(), .operation = if (self.draft_cb) |backend| backend.operationToken() else null }) catch platform.inference_process_supervisor.restartWorker();
            } else draft_fallback_state.deinit();
            const attached_draft_state = self.draft_decode_state;
            const use_contiguous_draft_state = ordinaryMetalGemmaDraftNeedsContiguousState(
                draft_cb.kind(),
                draft_gpt_config,
                if (attached_draft_state) |state| state.isPaged() else false,
            );
            const draft_ds = if (use_contiguous_draft_state)
                &draft_fallback_state
            else
                attached_draft_state orelse &draft_fallback_state;
            var draft_runtime = BorrowedDecodeStateRuntime.init(draft_ds);
            var decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);

            // Prefill draft model with the same prompt
            try draft_runtime.notePrefill(seq_len);

            var draft_pipeline = self.makeSpeculativeDraftPipeline(draft_cb, draft_gpt_config);
            var draft_request_finish: graph_mod.model_runtime.RequestFinish = .{};
            draft_pipeline.request_finish = &draft_request_finish;
            draft_pipeline.execution_cleanup_owner = self.draft_execution_cleanup_owner;
            defer draft_pipeline.finishModelRuntimeRequest() catch platform.inference_process_supervisor.restartWorker();
            var mtp_activation = Gemma4MtpActivationState{
                .allocator = allocator,
                .draft_cb = &draft_pipeline.cb,
            };
            defer mtp_activation.deinit();

            const mtp_top_k_for_resident = gemma4MtpTopKDiagnosticCount();
            const can_use_resident_mtp =
                use_gemma4_mtp and
                gemma4_mtp.deviceResidentDraftAllowed(mtp_top_k_for_resident) and
                self.shouldUseGemma4MtpGreedyDeviceVerifier(
                    config,
                    if (token_table) |*tt| tt else null,
                    &json_grammar,
                    if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                    mtp_top_k_for_resident,
                ) and
                gemma4MtpResidentDraftBackendAllowed(draft_pipeline.cb.kind());
            if (can_use_resident_mtp) debugGemma4Mtp("resident setup enabled", .{});

            // Prefill an ordinary draft model. Gemma 4 MTP assistants are not
            // standalone decoders: they are seeded from target activations and
            // target KV during each draft round.
            if (!use_gemma4_mtp) {
                try setWorkloadProfileRegime(&draft_pipeline.cb, .prefill);
                const draft_ctx = draft_runtime.makeDecodeContext(seq_len, seq_len);
                const draft_prefill_logits = try draft_pipeline.forwardAllLogits(token_ids[0..seq_len], 1, seq_len, &draft_ctx);
                allocator.free(draft_prefill_logits);
            }

            // Also prefill the target if we haven't yet (non-chunked path)
            var mtp_first_outcome: ?SampleOutcome = null;
            if (prefill_last_logits == null) {
                if (use_gemma4_mtp) {
                    if (prefill_greedy_token) |token| {
                        debugGemma4Mtp("first_token_prefill cached_greedy token={d}", .{token});
                        mtp_first_outcome = .{
                            .token = token,
                            .grammar_complete = false,
                        };
                    }
                    if (mtp_first_outcome) |_| {
                        const seeded_from_prefill = if (prefill_last_hidden) |hidden|
                            try self.replaceGemma4MtpActivationFromPrefillHidden(
                                &mtp_activation,
                                hidden,
                                prefill_last_hidden_rows,
                                mtp_hidden_source,
                                can_use_resident_mtp,
                                &draft_pipeline.cb,
                            )
                        else
                            false;
                        if (!seeded_from_prefill) {
                            try self.replaceGemma4MtpActivationFromPrompt(
                                &mtp_activation,
                                token_ids[0..seq_len],
                                seq_len,
                                mtp_hidden_source,
                                can_use_resident_mtp,
                                &draft_pipeline.cb,
                            );
                        }
                    } else {
                        debugGemma4Mtp("first_token_prefill host_logits_fallback", .{});
                        var seed_state = NativeDecodeState.initContiguous(allocator);
                        defer seed_state.deinit();
                        seed_state.configureForGptConfig(self.gpt_config);
                        var seed_runtime = BorrowedDecodeStateRuntime.init(&seed_state);
                        const target_ctx = seed_runtime.makeDecodeContext(seq_len, seq_len);
                        var target_prefill = try self.forwardAllLogitsAndHiddenHost(token_ids[0..seq_len], 1, seq_len, &target_ctx);
                        defer target_prefill.deinit();
                        prefill_last_logits = try allocator.dupe(
                            f32,
                            target_prefill.logits[(seq_len - 1) * vocab_size ..][0..vocab_size],
                        );
                        if (can_use_resident_mtp) {
                            const seeded_from_prefill = if (prefill_last_hidden) |hidden|
                                try self.replaceGemma4MtpActivationFromPrefillHidden(
                                    &mtp_activation,
                                    hidden,
                                    prefill_last_hidden_rows,
                                    mtp_hidden_source,
                                    true,
                                    &draft_pipeline.cb,
                                )
                            else
                                false;
                            if (!seeded_from_prefill) {
                                try self.replaceGemma4MtpActivationFromPrompt(
                                    &mtp_activation,
                                    token_ids[0..seq_len],
                                    seq_len,
                                    mtp_hidden_source,
                                    true,
                                    &draft_pipeline.cb,
                                );
                            }
                        } else {
                            mtp_activation.replaceHost(try self.dupeMtpTargetHiddenRow(&target_prefill, seq_len - 1, mtp_hidden_source));
                        }
                    }
                } else {
                    const target_ctx = decode_runtime.makeDecodeContext(seq_len, seq_len);
                    const target_prefill_logits = try self.forwardAllLogits(token_ids[0..seq_len], 1, seq_len, &target_ctx);
                    defer allocator.free(target_prefill_logits);
                    prefill_last_logits = try allocator.dupe(
                        f32,
                        target_prefill_logits[(seq_len - 1) * vocab_size ..][0..vocab_size],
                    );
                }
            } else if (use_gemma4_mtp and mtp_activation.host == null and mtp_activation.device == null) {
                const seeded_from_prefill = if (prefill_last_hidden) |hidden|
                    try self.replaceGemma4MtpActivationFromPrefillHidden(
                        &mtp_activation,
                        hidden,
                        prefill_last_hidden_rows,
                        mtp_hidden_source,
                        can_use_resident_mtp,
                        &draft_pipeline.cb,
                    )
                else
                    false;
                if (!seeded_from_prefill) {
                    try self.replaceGemma4MtpActivationFromPrompt(
                        &mtp_activation,
                        token_ids[0..seq_len],
                        seq_len,
                        mtp_hidden_source,
                        can_use_resident_mtp,
                        &draft_pipeline.cb,
                    );
                }
            }

            // Use prefill last logits for the first token
            try setWorkloadProfileRegime(&self.cb, .decode);
            const first_outcome = mtp_first_outcome orelse try self.sampleNextToken(
                prefill_last_logits.?,
                config,
                &penalty_state,
                if (token_table) |*tt| tt else null,
                &json_grammar,
                if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
            );
            const first_token = first_outcome.token;
            const first_is_eos = self.shouldStopOnEos(config, first_token, native_work_enabled);
            var callback_allows_generation = true;
            if (!first_is_eos) {
                token_ids[seq_len] = @intCast(first_token);
                seq_len += 1;
                tokens_generated += 1;
                if (!use_gemma4_mtp) {
                    _ = try decode_runtime.appendGeneratedToken();
                    _ = try draft_runtime.appendGeneratedToken();
                }
                try penalty_state.noteToken(allocator, @intCast(first_token));
                if (stream_enabled) {
                    const keep_streaming = try self.emitDecodedDelta(
                        token_ids[prompt_token_count..seq_len],
                        &streaming_text,
                        on_token_fn.?,
                        on_token_ctx.?,
                    );
                    if (!keep_streaming) {
                        callback_allows_generation = false;
                        finish_reason = "stop";
                    }
                }
            }

            if (first_is_eos or first_outcome.grammar_complete) {
                finish_reason = "stop";
            }

            const enter_speculative_loop = shouldEnterSpeculativeDecodeLoop(
                callback_allows_generation,
                first_is_eos,
                first_outcome.grammar_complete,
            );
            if (use_gemma4_mtp and enter_speculative_loop) {
                mtp_activation.cached_target_choice = try self.materializeAcceptedTokenKvForMtp(token_ids, seq_len, decode_state, mtp_hidden_source);
            }

            // Speculative decode loop
            if (enter_speculative_loop) {
                var mtp_zero_match_rounds: usize = 0;
                const mtp_zero_match_fallback_rounds: usize = if (use_gemma4_mtp)
                    platform.env.getenvUsize("ANTFLY_GEMMA4_MTP_ZERO_MATCH_FALLBACK_ROUNDS") orelse default_mtp_zero_match_fallback_rounds
                else
                    default_mtp_zero_match_fallback_rounds;
                const mtp_acceptance_probe_drafts: usize = if (use_gemma4_mtp)
                    gemma4MtpAcceptanceProbeDrafts()
                else
                    0;
                const mtp_min_acceptance_permille: usize = if (use_gemma4_mtp)
                    gemma4MtpMinAcceptancePermille()
                else
                    0;
                const mtp_adaptive_enabled = use_gemma4_mtp and speculation_policy == .auto and gemma4MtpAdaptiveKEnabled();
                const mtp_policy_max_k: usize = if (use_gemma4_mtp and speculation_policy == .auto)
                    @max(@as(usize, 1), @min(@as(usize, @intCast(config.speculative_k)), gemma4MtpAutoMaxK()))
                else
                    @as(usize, @intCast(config.speculative_k));
                var mtp_adaptive_k = MtpAdaptiveKPolicy.initFromValues(
                    mtp_policy_max_k,
                    mtp_min_acceptance_permille,
                    mtp_acceptance_probe_drafts,
                    mtp_adaptive_enabled,
                    gemma4MtpProbeK(),
                );
                const mtp_effective_zero_match_fallback_rounds =
                    gemma4MtpEffectiveZeroMatchFallbackRounds(mtp_zero_match_fallback_rounds, use_gemma4_mtp and mtp_adaptive_k.enabled);
                const mtp_auto_cost_probe_rounds: usize = if (use_gemma4_mtp and speculation_policy == .auto)
                    gemma4MtpAutoCostProbeRounds()
                else
                    0;
                const mtp_auto_min_accepted_per_round_milli: usize = if (use_gemma4_mtp and speculation_policy == .auto)
                    gemma4MtpAutoMinAcceptedPerRoundMilli()
                else
                    0;
                var mtp_acceptance_gate_checked = false;
                while (tokens_generated < max_tokens) {
                    if (self.failure_trace) |trace| trace.decoded_tokens = tokens_generated;
                    if (self.execution_control) |control| try control.update(.executing, @intCast(tokens_generated), @intCast(max_tokens));
                    const remaining = max_tokens - tokens_generated;
                    const step_k = if (use_gemma4_mtp)
                        mtp_adaptive_k.nextK(remaining)
                    else
                        @min(@as(usize, @intCast(config.speculative_k)), remaining);

                    const round_trace = enableGemma4MtpVerifyTrace();
                    const round_started_at = mtpProfileTimestamp(round_trace, self.io);
                    const result = if (use_gemma4_mtp)
                        try self.speculativeDecodeGemma4Mtp(
                            &draft_pipeline,
                            token_ids,
                            &seq_len,
                            decode_state,
                            config,
                            step_k,
                            remaining,
                            &penalty_state,
                            if (token_table) |*tt| tt else null,
                            &json_grammar,
                            if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                            &mtp_activation,
                            &speculative_stats.mtp_profile,
                        )
                    else
                        try self.speculativeDecode(
                            &draft_pipeline,
                            token_ids,
                            &seq_len,
                            decode_state,
                            draft_ds,
                            config,
                            step_k,
                            remaining,
                            &penalty_state,
                            if (token_table) |*tt| tt else null,
                            &json_grammar,
                            if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                        );

                    if (round_trace) {
                        std.debug.print(
                            "mtp-round-trace: round_us={d} drafted={d} accepted={d} bonus={}\n",
                            .{
                                @divTrunc(mtpProfileElapsedNs(true, self.io, round_started_at), std.time.ns_per_us),
                                result.drafted,
                                result.accepted,
                                result.had_bonus,
                            },
                        );
                    }
                    speculative_stats.rounds += 1;
                    speculative_stats.drafted_tokens += result.drafted;
                    speculative_stats.matched_draft_tokens += result.matched_drafts;
                    speculative_stats.accepted_tokens += result.accepted;
                    speculative_stats.correction_tokens += @intFromBool(result.correction_added);
                    speculative_stats.bonus_tokens += @intFromBool(result.had_bonus);
                    speculative_stats.mtp_quality.merge(result.mtp_quality);

                    const mtp_adaptive_decision = if (use_gemma4_mtp)
                        mtp_adaptive_k.observe(result.drafted, result.matched_drafts)
                    else
                        MtpAdaptiveKDecision.keep;

                    if (use_gemma4_mtp and result.drafted > 0) {
                        if (result.matched_drafts == 0) {
                            mtp_zero_match_rounds += 1;
                        } else {
                            mtp_zero_match_rounds = 0;
                        }
                    }

                    tokens_generated += result.accepted;
                    if (stream_enabled and result.accepted > 0) {
                        const keep_streaming = try self.emitDecodedDelta(
                            token_ids[prompt_token_count..seq_len],
                            &streaming_text,
                            on_token_fn.?,
                            on_token_ctx.?,
                        );
                        if (!keep_streaming) {
                            finish_reason = "stop";
                            break;
                        }
                    }

                    if (self.scheduler) |scheduler| {
                        if (self.scheduler_lease) |lease| {
                            scheduler.noteDecodeProgress(lease, tokens_generated);
                        }
                    }

                    if (result.hit_eos or result.hit_grammar_stop) {
                        finish_reason = "stop";
                        break;
                    }

                    const mtp_accepted_per_round_milli: usize = if (speculative_stats.rounds == 0)
                        0
                    else
                        (speculative_stats.accepted_tokens * 1000) / speculative_stats.rounds;
                    const mtp_cost_gate_should_fallback = use_gemma4_mtp and
                        speculation_policy == .auto and
                        mtp_auto_cost_probe_rounds > 0 and
                        mtp_auto_min_accepted_per_round_milli > 0 and
                        speculative_stats.rounds >= mtp_auto_cost_probe_rounds and
                        tokens_generated < max_tokens and
                        mtp_accepted_per_round_milli < mtp_auto_min_accepted_per_round_milli;

                    const mtp_acceptance_gate_should_fallback = use_gemma4_mtp and
                        speculation_policy == .auto and
                        tokens_generated < max_tokens and
                        if (mtp_adaptive_k.enabled)
                            mtp_adaptive_decision == .fallback
                        else
                            (!mtp_acceptance_gate_checked and
                                mtp_acceptance_probe_drafts > 0 and
                                speculative_stats.drafted_tokens >= mtp_acceptance_probe_drafts and
                                speculative_stats.acceptancePermille() < mtp_min_acceptance_permille);

                    if (use_gemma4_mtp and
                        (mtp_cost_gate_should_fallback or mtp_acceptance_gate_should_fallback))
                    {
                        if (!mtp_adaptive_k.enabled) mtp_acceptance_gate_checked = true;
                        speculative_stats.adaptive_fallbacks += 1;
                        if (mtp_acceptance_gate_should_fallback) {
                            speculative_stats.mtp_acceptance_gate_fallbacks += 1;
                        }
                        speculative_stats.speculation_policy_decision = if (mtp_cost_gate_should_fallback)
                            .disabled_slow
                        else
                            .disabled_low_acceptance;
                        debugGemma4Mtp(
                            "auto gate fallback drafted={d} matched={d} acceptance_permille={d} threshold_permille={d} accepted_per_round_milli={d} threshold_accepted_per_round_milli={d}",
                            .{
                                speculative_stats.drafted_tokens,
                                speculative_stats.matched_draft_tokens,
                                speculative_stats.acceptancePermille(),
                                mtp_min_acceptance_permille,
                                mtp_accepted_per_round_milli,
                                mtp_auto_min_accepted_per_round_milli,
                            },
                        );
                        try self.flushPendingGemma4MtpMaterialize(
                            token_ids,
                            seq_len,
                            decode_state,
                            &mtp_activation,
                            mtp_hidden_source,
                            &speculative_stats.mtp_profile,
                        );
                        var fallback_prefill_logits: ?[]f32 = null;
                        defer if (fallback_prefill_logits) |logits| allocator.free(logits);
                        var fallback_greedy_token: ?usize = null;
                        const fallback_started_at = mtpProfileTimestamp(speculative_stats.mtp_profile.enabled, self.io);
                        try setWorkloadProfileRegime(&self.cb, .decode);
                        const fallback = try self.standardDecode(
                            token_ids,
                            &seq_len,
                            decode_state,
                            &selected_request,
                            config,
                            &fallback_prefill_logits,
                            &fallback_greedy_token,
                            &penalty_state,
                            if (token_table) |*tt| tt else null,
                            &json_grammar,
                            if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                            0,
                            max_tokens - tokens_generated,
                            prompt_token_count,
                            if (stream_enabled) on_token_fn else null,
                            if (stream_enabled) on_token_ctx else null,
                            if (stream_enabled) &streaming_text else null,
                            native_work_enabled,
                        );
                        if (speculative_stats.mtp_profile.enabled) {
                            speculative_stats.mtp_profile.fallback_calls += 1;
                            speculative_stats.mtp_profile.fallback_ns +|= mtpProfileElapsedNs(true, self.io, fallback_started_at);
                        }
                        tokens_generated += fallback.tokens_generated;
                        finish_reason = fallback.finish_reason;
                        break;
                    }

                    if (use_gemma4_mtp and speculation_policy == .auto and mtp_effective_zero_match_fallback_rounds > 0 and mtp_zero_match_rounds >= mtp_effective_zero_match_fallback_rounds and tokens_generated < max_tokens) {
                        speculative_stats.adaptive_fallbacks += 1;
                        speculative_stats.speculation_policy_decision = .disabled_zero_match;
                        try self.flushPendingGemma4MtpMaterialize(
                            token_ids,
                            seq_len,
                            decode_state,
                            &mtp_activation,
                            mtp_hidden_source,
                            &speculative_stats.mtp_profile,
                        );
                        var fallback_prefill_logits: ?[]f32 = null;
                        defer if (fallback_prefill_logits) |logits| allocator.free(logits);
                        var fallback_greedy_token: ?usize = null;
                        const fallback_started_at = mtpProfileTimestamp(speculative_stats.mtp_profile.enabled, self.io);
                        try setWorkloadProfileRegime(&self.cb, .decode);
                        const fallback = try self.standardDecode(
                            token_ids,
                            &seq_len,
                            decode_state,
                            &selected_request,
                            config,
                            &fallback_prefill_logits,
                            &fallback_greedy_token,
                            &penalty_state,
                            if (token_table) |*tt| tt else null,
                            &json_grammar,
                            if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                            0,
                            max_tokens - tokens_generated,
                            prompt_token_count,
                            if (stream_enabled) on_token_fn else null,
                            if (stream_enabled) on_token_ctx else null,
                            if (stream_enabled) &streaming_text else null,
                            native_work_enabled,
                        );
                        if (speculative_stats.mtp_profile.enabled) {
                            speculative_stats.mtp_profile.fallback_calls += 1;
                            speculative_stats.mtp_profile.fallback_ns +|= mtpProfileElapsedNs(true, self.io, fallback_started_at);
                        }
                        tokens_generated += fallback.tokens_generated;
                        finish_reason = fallback.finish_reason;
                        break;
                    }

                    if (result.accepted == 0) break; // safety valve
                }
            }
        }

        // Standard autoregressive loop (skipped when speculative decoding was used above)
        if (!use_speculative and !prefill_decode_complete) {
            try setWorkloadProfileRegime(&self.cb, .decode);
            debugGenerationStage(
                "entering standard decode max_tokens={d} prompt_token_count={d}",
                .{ max_tokens, prompt_token_count },
            );
            const decode_result = try self.standardDecode(
                token_ids,
                &seq_len,
                decode_state,
                &selected_request,
                config,
                &prefill_last_logits,
                &prefill_greedy_token,
                &penalty_state,
                if (token_table) |*tt| tt else null,
                &json_grammar,
                if (gbnf_grammar != null) &(gbnf_grammar.?) else null,
                tokens_generated,
                max_tokens,
                prompt_token_count,
                if (stream_enabled) on_token_fn else null,
                if (stream_enabled) on_token_ctx else null,
                if (stream_enabled) &streaming_text else null,
                native_work_enabled,
            );
            tokens_generated = decode_result.tokens_generated;
            finish_reason = decode_result.finish_reason;
            pending_unmaterialized_tokens = decode_result.pending_unmaterialized_tokens;
            if (decode_result.prompt_lookup.target_verify_passes != 0) {
                speculative_stats.prompt_lookup_enabled = true;
                speculative_stats.prompt_lookup = decode_result.prompt_lookup;
                speculative_stats.rounds = @intCast(decode_result.prompt_lookup.target_verify_passes);
                speculative_stats.drafted_tokens = @intCast(decode_result.prompt_lookup.proposed_tokens);
                speculative_stats.matched_draft_tokens = @intCast(decode_result.prompt_lookup.accepted_proposal_tokens);
                speculative_stats.accepted_tokens = @intCast(decode_result.prompt_lookup.accepted_proposal_tokens);
                speculative_stats.speculation_policy_decision = .active;
            }
            debugGenerationStage(
                "standard decode returned tokens_generated={d} finish_reason={s} seq_len={d}",
                .{ tokens_generated, finish_reason, seq_len },
            );
        }

        if (tokens_generated > 0) {
            if (self.prompt_cache) |cache| if (cache.generatedPrefixStoreEnabled()) {
                var cache_scope = if (self.execution_lock) |mutex| self.lockExecution(mutex) catch |err| unavailable: {
                    std.log.warn("radix continuation cache scope unavailable: {s}", .{@errorName(err)});
                    break :unavailable null;
                } else null;
                defer if (cache_scope) |*scope| scope.deinit();
                if (self.execution_lock == null or cache_scope != null)
                    decoder_storage.storeGeneratedPromptPrefix(&self.cb, prefix_binding, decode_state, &self.gpt_config, self.prompt_cache, prefix_request, token_ids[0 .. seq_len - 1]);
            };
        }

        // Decode only the generated tokens. By default channel-aware models
        // project public text and token IDs from the same slice. The explicit
        // local diagnostic opt-in may retain raw IDs while text stays public.
        const gen_start = prompt_token_count;
        const final_channel_end_token_id = streaming_text.final_channel_end_token_id;
        const turn_end_token_id = streaming_text.turn_end_token_id;
        const raw_gen_token_ids = token_ids[gen_start..seq_len];
        if (streaming_text.canonical) |*projection| projection.update(raw_gen_token_ids);
        const projected_gen_token_ids = if (streaming_text.canonical) |projection| projection.publicTokens(raw_gen_token_ids) else finalResponseTokenSlice(
            token_ids[gen_start..seq_len],
            streaming_text.final_channel_required,
            streaming_text.final_channel_preopened,
            final_channel_end_token_id,
            streaming_text.final_channel_header_token_ids,
            streaming_text.channel_start_token_id,
            turn_end_token_id,
        );
        const reasoning_gen_token_ids = if (streaming_text.canonical) |projection| projection.thoughtTokens(raw_gen_token_ids) else reasoningResponseTokenSlice(
            raw_gen_token_ids,
            streaming_text.final_channel_required,
            streaming_text.final_channel_preopened,
            final_channel_end_token_id,
            streaming_text.final_channel_header_token_ids,
            streaming_text.channel_start_token_id,
            turn_end_token_id,
        );
        const result_gen_token_ids = generationResultTokenSlice(
            raw_gen_token_ids,
            projected_gen_token_ids,
            self.return_raw_token_ids or config.return_raw_token_ids,
        );
        const result_gen_ids = try allocator.alloc(i32, result_gen_token_ids.len);
        errdefer allocator.free(result_gen_ids);
        for (result_gen_token_ids, 0..) |token_id, idx| result_gen_ids[idx] = @intCast(token_id);

        const text_gen_ids = if (self.return_raw_token_ids or config.return_raw_token_ids) blk: {
            const ids = try allocator.alloc(i32, projected_gen_token_ids.len);
            for (projected_gen_token_ids, 0..) |token_id, idx| ids[idx] = @intCast(token_id);
            break :blk ids;
        } else result_gen_ids;
        defer if (self.return_raw_token_ids or config.return_raw_token_ids) allocator.free(text_gen_ids);

        const result_eos_token_ids: ?[]i32 = if (config.return_raw_token_ids and config.fixed_length_mask_eos) blk: {
            var eos_storage: [gpt_mod.max_extra_eos_token_ids + 1]i32 = undefined;
            var eos_len: usize = 0;
            if (self.gpt_config.eos_token_id >= 0) {
                eos_storage[eos_len] = self.gpt_config.eos_token_id;
                eos_len += 1;
            }
            for (self.gpt_config.extra_eos_token_ids[0..self.gpt_config.extra_eos_token_ids_len]) |eos| {
                if (eos < 0 or std.mem.indexOfScalar(i32, eos_storage[0..eos_len], eos) != null) continue;
                eos_storage[eos_len] = eos;
                eos_len += 1;
            }
            break :blk try allocator.dupe(i32, eos_storage[0..eos_len]);
        } else null;
        errdefer if (result_eos_token_ids) |ids| allocator.free(ids);
        const result_suppress_token_ids: ?[]i32 = if (config.return_raw_token_ids and config.fixed_length_mask_eos)
            try allocator.dupe(i32, config.effectiveSuppressTokenIds(&self.gpt_config))
        else
            null;
        errdefer if (result_suppress_token_ids) |ids| allocator.free(ids);

        // Channel-protocol debugging: report whether the final-channel marker
        // tokens resolved against this tokenizer. A null marker means the
        // projection strips every generated token regardless of model output.
        // (Raw ids/text are available via return_raw_token_ids.)
        if (getenvBool("ANTFLY_GENERATION_DEBUG_RAW_OUTPUT")) {
            std.debug.print(
                "channel_protocol: required={} channel_end={?d} channel_start={?d} turn_end={?d} header_len={d} saw_final={}\n",
                .{
                    streaming_text.final_channel_required,
                    streaming_text.final_channel_end_token_id,
                    streaming_text.channel_start_token_id,
                    streaming_text.turn_end_token_id,
                    streaming_text.final_channel_header_token_ids.len,
                    streaming_text.saw_final_channel,
                },
            );
        }

        const text_decode_started_at = if (self.io) |io| std.Io.Timestamp.now(io, .awake) else std.Io.Timestamp.zero;
        if (self.failure_trace) |trace| trace.mark(.text_decode);
        const text = if (token_table) |*table| try table.decodeTokens(allocator, text_gen_ids) else try self.tokenizer.decode(allocator, text_gen_ids);
        errdefer allocator.free(text);
        const reasoning_text = if (reasoning_gen_token_ids.len > 0) blk: {
            const reasoning_ids = try allocator.alloc(i32, reasoning_gen_token_ids.len);
            defer allocator.free(reasoning_ids);
            for (reasoning_gen_token_ids, 0..) |token_id, idx| reasoning_ids[idx] = @intCast(token_id);
            break :blk try self.tokenizer.decode(allocator, reasoning_ids);
        } else null;
        errdefer if (reasoning_text) |reasoning| allocator.free(reasoning);
        if (stream_enabled) {
            _ = emitCompletedProjectionDelta(
                &streaming_text,
                on_token_ctx.?,
                on_token_fn.?,
                text,
            );
        }
        const finished_generate_at = if (self.io) |io| std.Io.Timestamp.now(io, .awake) else std.Io.Timestamp.zero;
        var timing_ms: ?GenerationTimingMs = if (self.io != null) GenerationTimingMs.fromElapsedMs(.{
            timestampDurationMillis(started_at, formatted_prompt_at),
            timestampDurationMillis(started_at, encoded_prompt_at),
            timestampDurationMillis(started_at, runtime_prepare_started_at),
            timestampDurationMillis(started_at, prefill_started_at),
            timestampDurationMillis(started_at, finished_prefill_at),
            timestampDurationMillis(started_at, finished_maintenance_at),
            timestampDurationMillis(started_at, text_decode_started_at),
            timestampDurationMillis(started_at, finished_generate_at),
        }) else null;
        if (timing_ms) |*timing| {
            if (timed_callback.first) |first| timing.first_token = timestampDurationMillis(started_at, first);
        }
        if (timing_ms) |timing| if (self.generation_admission) |lane| lane.notePipeline(timing.prefill, timing.decode);
        if (self.print_timing and timing_ms != null) {
            const timing = timing_ms.?;
            std.debug.print(
                "generate_timing_ms: prompt_format={d} tokenize={d} multimodal_prepare={d} runtime_prepare={d} prefill={d} maintenance={d} decode={d} text_decode={d} total={d}\n",
                .{
                    timing.prompt_format,
                    timing.tokenize,
                    timing.multimodal_prepare,
                    timing.runtime_prepare,
                    timing.prefill,
                    timing.maintenance,
                    timing.decode,
                    timing.text_decode,
                    timing.total,
                },
            );
        }
        if (packed_grant_profile) {
            const grant = config.native_checkpoint_operator_grant.?;
            const before = packed_profile_before.?;
            const after_prefill = packed_profile_after_prefill.?;
            const after_decode = packedGrantProfileSnapshot(self);
            std.debug.print(
                "packed_grant_profile {{\"schema\":\"antfly.packed-grant-profile.v1\",\"request\":{},\"route\":\"{s}\",\"qualification_arm\":\"{s}\",\"prefill_forward_attempts\":{},\"prefill_prepared_token_successes\":{},\"prefill_canonical_last_logits_calls\":{},\"prefill_decoder_calls\":{},\"prefill_block_ns\":{},\"prefill_attention_ns\":{},\"prefill_ffn_ns\":{},\"decode_forward_attempts\":{},\"decode_prepared_token_successes\":{},\"decode_canonical_last_logits_calls\":{},\"decode_decoder_calls\":{},\"decode_block_ns\":{},\"decode_attention_ns\":{},\"decode_ffn_ns\":{},\"frame_submits\":{},\"frame_wait_ns\":{},\"frame_gpu_ns\":{},\"compute_encoders\":{},\"blit_encoders\":{},\"host_download_bytes\":{},\"to_host_calls\":{},\"packed_framed_attention_dispatches\":{},\"packed_standalone_attention_dispatches\":{},\"packed_split_decode_dispatches\":{},\"packed_flash_prefill_dispatches\":{}}}\n",
                .{
                    grant.request_id,
                    @tagName(grant.route),
                    @tagName(grant.arm),
                    after_prefill.debug.forward_attempts -| before.debug.forward_attempts,
                    after_prefill.debug.prepared_token_successes -| before.debug.prepared_token_successes,
                    after_prefill.debug.canonical_last_logits_calls -| before.debug.canonical_last_logits_calls,
                    after_prefill.decoder.prefill_calls -| before.decoder.prefill_calls,
                    after_prefill.decoder.prefill_block_nanos -| before.decoder.prefill_block_nanos,
                    after_prefill.decoder.prefill_block_attention_nanos -| before.decoder.prefill_block_attention_nanos,
                    after_prefill.decoder.prefill_block_ffn_nanos -| before.decoder.prefill_block_ffn_nanos,
                    after_decode.debug.forward_attempts -| after_prefill.debug.forward_attempts,
                    after_decode.debug.prepared_token_successes -| after_prefill.debug.prepared_token_successes,
                    after_decode.debug.canonical_last_logits_calls -| after_prefill.debug.canonical_last_logits_calls,
                    after_decode.decoder.greedy_calls -| after_prefill.decoder.greedy_calls,
                    after_decode.decoder.greedy_block_nanos -| after_prefill.decoder.greedy_block_nanos,
                    after_decode.decoder.greedy_block_attention_nanos -| after_prefill.decoder.greedy_block_attention_nanos,
                    after_decode.decoder.greedy_block_ffn_nanos -| after_prefill.decoder.greedy_block_ffn_nanos,
                    after_decode.frame_submits -| before.frame_submits,
                    after_decode.frame_wait_ns -| before.frame_wait_ns,
                    after_decode.frame_gpu_ns -| before.frame_gpu_ns,
                    after_decode.compute_encoders -| before.compute_encoders,
                    after_decode.blit_encoders -| before.blit_encoders,
                    after_decode.host_download_bytes -| before.host_download_bytes,
                    after_decode.to_host_calls -| before.to_host_calls,
                    decode_state.last_context_framed_attention_dispatches,
                    decode_state.last_context_standalone_attention_dispatches,
                    decode_state.last_context_split_decode_dispatches,
                    decode_state.last_context_flash_prefill_dispatches,
                },
            );
        }
        if (ocr_profile_start) |before| {
            const after = self.cb.debugTimingSnapshot().provider;
            std.log.info("metal_ocr_profile: decode_attempts={d} decode_hits={d} decode_fallbacks={d} frame_submits={d} frame_wait_ns={d} frame_gpu_ns={d} host_download_bytes={d} to_host_calls={d}", .{
                after.active_decode_frame_attempts -| before.active_decode_frame_attempts,
                after.active_decode_frame_successes -| before.active_decode_frame_successes,
                after.active_decode_frame_fallbacks -| before.active_decode_frame_fallbacks,
                after.decoder_runtime_frame_submits -| before.decoder_runtime_frame_submits,
                after.decoder_runtime_frame_wait_nanos -| before.decoder_runtime_frame_wait_nanos,
                after.decoder_runtime_frame_gpu_nanos -| before.decoder_runtime_frame_gpu_nanos,
                after.metal_tensor_host_mirror_download_bytes -| before.metal_tensor_host_mirror_download_bytes,
                after.metal_tensor_to_host_device_calls -| before.metal_tensor_to_host_device_calls,
            });
        }
        const final_mtp_auto_cost_probe_rounds: usize = if (speculative_stats.mtp_enabled and speculation_policy == .auto)
            gemma4MtpAutoCostProbeRounds()
        else
            0;
        const final_mtp_auto_min_accepted_per_round_milli: usize = if (speculative_stats.mtp_enabled and speculation_policy == .auto)
            gemma4MtpAutoMinAcceptedPerRoundMilli()
        else
            0;
        if (speculative_stats.mtp_enabled and
            speculation_policy == .auto and
            speculative_stats.speculation_policy_decision == .active and
            final_mtp_auto_cost_probe_rounds > 0 and
            speculative_stats.rounds < final_mtp_auto_cost_probe_rounds)
        {
            speculative_stats.speculation_policy_decision = .disabled_insufficient_probe;
            speculative_stats.mtp_disabled_reason = "mtp_auto_insufficient_cost_probe";
        } else if (speculative_stats.mtp_enabled and
            speculation_policy == .auto and
            speculative_stats.speculation_policy_decision == .active and
            final_mtp_auto_cost_probe_rounds > 0 and
            final_mtp_auto_min_accepted_per_round_milli > 0 and
            speculative_stats.rounds >= final_mtp_auto_cost_probe_rounds)
        {
            const accepted_per_round_milli = (speculative_stats.accepted_tokens * 1000) / speculative_stats.rounds;
            if (accepted_per_round_milli < final_mtp_auto_min_accepted_per_round_milli) {
                speculative_stats.speculation_policy_decision = .disabled_slow;
                speculative_stats.mtp_disabled_reason = "mtp_auto_cost_probe_slow";
            }
        }
        if (speculative_stats.mtp_enabled and platform.env.getenvBoolDefault("ANTFLY_GEMMA4_OCR_PROFILE", false)) {
            std.log.info("metal_ocr_mtp_profile: rounds={d} drafted={d} matched={d} accepted={d} corrections={d} bonus={d}", .{
                speculative_stats.rounds,          speculative_stats.drafted_tokens,    speculative_stats.matched_draft_tokens,
                speculative_stats.accepted_tokens, speculative_stats.correction_tokens, speculative_stats.bonus_tokens,
            });
        }
        if (speculative_stats.mtp_profile.enabled) {
            const profile = speculative_stats.mtp_profile;
            // Report existing phase counters without inserting GPU fences.
            // These are wall times, not independent GPU kernel durations.
            std.log.info("mtp_phase_profile: sync={any} draft_ns={d} verify_ns={d} materialize_ns={d} activation_ns={d} fallback_ns={d} draft_steps={d} cached_seeds={d} verify_calls={d} verify_rows={d} materializations={d} corrections={d} bonus={d} deferred={d} runtime_hits={d} runtime_fallbacks={d}", .{
                profile.sync_enabled,                profile.draft_token_ns,            profile.target_verify_ns,
                profile.materialization_ns,          profile.activation_copy_ns,        profile.fallback_ns,
                profile.draft_steps,                 profile.cached_target_seeds,       profile.target_verify_calls,
                profile.target_verify_rows,          profile.materializations,          profile.correction_materializations,
                profile.bonus_materializations,      profile.deferred_materializations, profile.dedicated_runtime_hits,
                profile.dedicated_runtime_fallbacks,
            });
            std.log.info("mtp_draft_profile: embedding_ns={d} concat_ns={d} preprojection_ns={d} assistant_ns={d} postprojection_ns={d} head_ns={d} selection_ns={d} argmax_ns={d} resident_steps={d} host_steps={d} cross_copies={d}", .{
                profile.draft_target_embedding_ns, profile.draft_concat_ns,                     profile.draft_preprojection_ns,
                profile.draft_assistant_ns,        profile.draft_postprojection_ns,             profile.draft_lm_head_ns,
                profile.draft_selection_ns,        profile.draft_argmax_ns,                     profile.resident_draft_steps,
                profile.host_draft_steps,          profile.draft_target_embedding_cross_copies,
            });
        }
        if (config.metal_native_checkpoint_qualification and
            config.metal_checkpoint_qualification_route != .none and
            self.cb.kind() == .metal)
        {
            if (pending_unmaterialized_tokens > 1 or pending_unmaterialized_tokens > decode_state.total_tokens)
                return error.InvalidKvCheckpoint;
            if (decode_state.total_tokens != seq_len) return error.InvalidKvCheckpoint;
            self.metal_qualification_completion = try metalQualificationCompletion(
                decode_state.total_tokens,
                decode_state.total_tokens - pending_unmaterialized_tokens,
                pending_unmaterialized_tokens,
            );
        }
        if (native_work_enabled) {
            debugNativeWorkIds(@intFromPtr(self), "raw_output", raw_gen_token_ids);
            debugNativeWorkIds(@intFromPtr(self), "public_output", result_gen_token_ids);
            std.debug.print("native_work_end: pipeline={d} supported={} generated_tokens={d} cached_prefix={d} finish_reason={s}\n", .{ @intFromPtr(self), native_work_supported, tokens_generated, cached_prompt_tokens, finish_reason });
            native_work_closed = true;
        }
        return .{
            .text = text,
            .reasoning_text = reasoning_text,
            .token_ids = result_gen_ids,
            .applied_suppress_token_ids = result_suppress_token_ids,
            .eos_token_ids = result_eos_token_ids,
            .fixed_length_mask_eos = config.fixed_length_mask_eos,
            .prompt_tokens = prompt_token_count,
            .tokens_used = tokens_generated,
            .finish_reason = finish_reason,
            .cached_prompt_tokens = cached_prompt_tokens,
            .timing_ms = timing_ms,
            .speculative = if (use_speculative or draft_requested or prompt_lookup_requested) speculative_stats else null,
            .teacher_forced_evidence = if (comptime builtin.is_test) quality_generation_evidence else {},
            .allocator = allocator,
        };
    }

    pub const PrefillOutput = decoder_prefill.Output;
    const capturePreparedTailPostNormHidden = decoder_prefill.Forward.capturePreparedTailPostNormHidden;
    const metalPreparedTailOwnsWholePrefill = decoder_prefill.Forward.metalPreparedTailOwnsWholePrefill;

    fn prefillRuntime(self: *NativeGenerationPipeline, state: *NativeDecodeState, mutex: ?*std.atomic.Mutex) decoder_prefill.Runtime {
        return .{
            .forward = self.physicalDecoder(),
            .state = state,
            .setup_execution = if (self.execution_lock) |lock| self.executionAccess(lock) else .{},
            .execution = if (mutex) |lock| self.executionAccess(lock) else .{ .io = self.io, .control = self.execution_control },
            .work_control = .{ .context = self, .check_fn = checkAttentionMatchQueryWork },
        };
    }

    /// Run the prefill phase: process prompt tokens through the model,
    /// either chunked (for paged KV) or in one pass. Returns the logits
    /// for the last prompt position, or null if handled by the scheduler.
    fn checkPrefillRequest(self: *const NativeGenerationPipeline) !void {
        if (self.execution_control) |control| try control.check();
        if (self.continue_fn) |should_continue| {
            const context = self.continue_ctx orelse return error.InvalidCallbackContext;
            if (!should_continue(context)) return error.Cancelled;
        }
    }

    fn executePrefill(
        self: *NativeGenerationPipeline,
        prompt_ids: []const i64,
        seq_len: usize,
        prefilled_tokens: usize,
        decode_state: *NativeDecodeState,
        config: GenerationConfig,
        allow_resident_greedy_token: bool,
        capture_last_hidden: bool,
        discard_final_output: bool,
    ) !PrefillOutput {
        // Cancellation must win before route planning touches model, graph, or
        // backend state. Besides avoiding wasted work, this keeps cancelled
        // requests safe when their backend has not been initialized yet.
        try self.checkPrefillRequest();
        if (discard_final_output and self.compiled_partition_backend != null)
            return error.UnsupportedCompactionCapturePrefill;
        const work_trace = enableGenerationStageDebug();
        var work_complete = true;
        if (work_trace) {
            std.debug.print("native_work_prefill_dispatch: pipeline={d} route=text source_tokens={d} cached_prefix={d} query_tokens={d}\n", .{ @intFromPtr(self), seq_len, prefilled_tokens, prompt_ids.len });
            debugNativeWorkIds(@intFromPtr(self), "dispatch_query", prompt_ids);
        }
        defer if (work_trace) {
            std.debug.print("native_work_prefill_result: pipeline={d} route=text completed={} query_tokens={d}\n", .{ @intFromPtr(self), work_complete, prompt_ids.len });
        };
        errdefer work_complete = false;
        var prompt_runtime = self.prefillRuntime(decode_state, null);
        const request = self.promptRequest(config, seq_len, prompt_ids.len, prefilled_tokens, allow_resident_greedy_token, capture_last_hidden);
        const prompt_plan = try prompt_runtime.planPrompt(request);
        const exact_prefill_probe = prompt_plan.exact_repeat_probe;
        var exact_prefill_calls: usize = 0;
        defer if (exact_prefill_probe) {
            std.log.info("attention_match_exact_prefill source_tokens={d} split_launches={d} diagnostic_only=1", .{ seq_len, exact_prefill_calls });
        };

        var prefill_last_logits: ?[]f32 = null;
        errdefer if (prefill_last_logits) |logits| self.allocator.free(logits);
        var prefill_greedy_token: ?usize = null;
        var prefill_last_hidden: ?ops.CT = null;
        var prefill_last_hidden_rows: usize = 0;
        errdefer if (prefill_last_hidden) |hidden| self.cb.free(hidden);
        const use_cuda_prefill_greedy_token = prompt_plan.cuda_greedy;
        const use_metal_prefill_greedy_token = prompt_plan.metal_greedy;
        const use_prefill_greedy_token = prompt_plan.greedy();
        const use_metal_target_last_logits = prompt_plan.metal_last_logits;
        const can_use_typed_prefill_outputs = prompt_plan.typed_outputs;
        const allow_shared_kv_prefill = prompt_plan.shared_kv;
        try prompt_runtime.preparePromptState(.{
            .prompt_tokens = seq_len,
            .generated_tokens = config.max_tokens,
            .fresh_cuda_capacity = allow_shared_kv_prefill,
            .prefilled_tokens = prefilled_tokens,
            .prompt_cache_enabled = config.prompt_cache_enabled,
            .has_prompt_cache = self.prompt_cache != null,
            .has_draft = self.draft_cb != null,
            .speculation_requested = config.speculation_requested,
        });
        const prefer_cuda_direct_last_logits = prompt_plan.cuda_last_logits;
        debugGenerationStage(
            "executePrefill enter seq_len={d} prefilled={d} query_len={d} paged={} scheduler={} compiled_whole_model={} prefill_greedy={}",
            .{
                seq_len,
                prefilled_tokens,
                prompt_ids.len,
                decode_state.isPaged(),
                self.scheduler != null,
                self.compiled_partition_backend != null and self.compiled_attachment_target == .whole_model and self.graph_cache != null,
                use_prefill_greedy_token,
            },
        );

        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| {
                scheduler.notePrefillProgress(lease, prefilled_tokens, seq_len);
            }
        }

        if (prompt_plan.compiled_whole_model) {
            const compiled = try prompt_runtime.prepareCompiledPrompt(request.compiled());
            const prefill_chunk_size = compiled.chunk_rows;
            debugGenerationStage(
                "executePrefill whole-model fast path seq_len={d} chunk_size={d} ring={}",
                .{ seq_len, prefill_chunk_size, decode_state.allow_swa_ring },
            );
            var window = try decoder_prefill.FixedWindow.init(prompt_ids.len, prefilled_tokens, prefill_chunk_size);
            while (window.next()) |attempt| {
                const chunk = prompt_ids[attempt.start..attempt.end];
                const total_chunk_end = attempt.total_end;
                const is_last_chunk = attempt.final;
                const phase_timer = @import("antfly_readers").pipeline_metrics.start(.prefill);
                defer phase_timer.finish();
                const wants_greedy = is_last_chunk and request.allow_resident_greedy and isPureGreedyConfig(config) and config.grammar == null;
                var compiled_prefill = self.prefillRuntime(decode_state, null);
                const output = compiled_prefill.runCompiledChunk(.{ .token_ids = chunk, .suppress_token_ids = config.effectiveSuppressTokenIds(&self.gpt_config), .total_sequence_length = total_chunk_end, .output = if (wants_greedy) .greedy_token else if (is_last_chunk) .last_logits else .kv_only }) catch |err| {
                    debugGenerationStage("executePrefill whole-model chunk failed chunk_start={d} chunk_end={d} err={s}", .{ attempt.start, attempt.end, @errorName(err) });
                    return err;
                };
                if (output.greedy_token != null) {
                    if (self.scheduler) |scheduler| {
                        if (self.scheduler_lease) |lease| {
                            scheduler.notePrefillProgress(lease, total_chunk_end, seq_len);
                            scheduler.finishTurn(lease, .prefill);
                        }
                    }
                    return .{ .greedy_token = output.greedy_token.? };
                }
                if (output.last_logits) |logits| prefill_last_logits = logits;
                if (self.scheduler) |scheduler| {
                    if (self.scheduler_lease) |lease| {
                        scheduler.notePrefillProgress(lease, total_chunk_end, seq_len);
                        if (is_last_chunk) scheduler.finishTurn(lease, .prefill);
                    }
                }
            }
            return .{ .last_logits = prefill_last_logits };
        }

        if (decode_state.isPaged() and seq_len > 1) {
            const query_len = prompt_ids.len;
            var cursor = try decoder_prefill.ChunkCursor.select(.{
                .query_tokens = query_len,
                .prefilled_tokens = prefilled_tokens,
                .prompt_tokens = seq_len,
                .greedy_output = use_prefill_greedy_token,
                .capture_hidden = capture_last_hidden,
                .execution_control = self.execution_control,
            }, .{
                .configured_plan = config.prefill_chunk_plan,
                .leased_plan = if (self.scheduler_lease) |lease| if (lease.prefill_chunk_plan.isAdmitted()) lease.prefill_chunk_plan else null else null,
                .configured_chunk_rows = config.prefill_chunk_size,
                .scheduler_chunk_rows = if (self.scheduler_lease) |lease| lease.prefill_chunk_size else 0,
                .default_chunk_rows = decoder_prefill.nativeChunkRows(&self.cb, self.gpt_config, seq_len, 0) orelse 0,
                .selected_kv = config.kv_cache_mode == .select_v1,
                .checkpoint_resume = self.checkpoint_resume != null,
                .backend = self.cb.kind(),
                .pure_greedy = isPureGreedyConfig(config) and config.grammar == null,
                .resident_greedy_allowed = request.allow_resident_greedy,
                .first_token_enabled = enableCudaPrefillFirstToken(),
                .coalesce_token_limit = cudaPrefillFirstTokenCoalesceTokenLimit(),
            });
            const admitted_plan = cursor.options.admitted_plan;
            switch (cursor.plan_decision) {
                .none => {},
                .bypassed_prompt_cache => |plan| std.log.info(
                    "prefill_chunk_plan: status=bypassed reason=prompt_cache_hit fingerprint={x} cached_tokens={d}",
                    .{ plan.fingerprint, prefilled_tokens },
                ),
                .bypassed_geometry => |plan| std.log.info(
                    "prefill_chunk_plan: status=bypassed reason=prompt_token_mismatch fingerprint={x} plan_prompt_tokens={d} pipeline_prompt_tokens={d}",
                    .{ plan.fingerprint, plan.prompt_tokens, query_len },
                ),
                .execute => |plan| {
                    const tail = plan.tail();
                    std.log.info(
                        "prefill_chunk_plan: status=execute fingerprint={x} selection={s} fairness={s} prompt_tokens={d} chunks={d} max_chunk_rows={d} max_scratch_bytes={d} forced_drain_budget_bytes={d} tail_rows={d} tail_weight_route={s}",
                        .{ plan.fingerprint, @tagName(plan.selection), @tagName(plan.fairness), plan.prompt_tokens, plan.chunks.len, plan.max_chunk_rows, plan.max_scratch_bytes, plan.forced_drain_budget_bytes, tail.rows, @tagName(tail.weight_route_hint) },
                    );
                },
            }
            if (cursor.options.first_token_coalesced) debugFirstToken(
                "prefill_first_token legacy_coalesced_prefill_chunk_size from={d} to={d} seq_len={d}",
                .{ cursor.uncoalesced_chunk_size, cursor.current_chunk_size, query_len },
            );
            prompt_runtime.prepareChunkWindow(request, cursor.current_chunk_size);
            while (try cursor.next(if (self.scheduler_lease) |lease| lease.prefill_chunk_size else cursor.current_chunk_size)) |attempt| {
                defer cursor.cancel(attempt) catch {};
                const processed = attempt.start;
                var direct_prefill_turn_acquired = false;
                defer if (direct_prefill_turn_acquired) {
                    self.scheduler.?.finishTurn(self.scheduler_lease.?, .prefill);
                };
                const planned_chunk = attempt.chunk;
                const chunk_size = planned_chunk.rows;
                const chunk_end = attempt.end;
                const total_chunk_end = attempt.total_end;
                const chunk = prompt_ids[processed..chunk_end];
                const output_intent: PrefillOutputIntent = if (discard_final_output) .kv_only else attempt.output_intent;
                debugGenerationStage(
                    "executePrefill chunk start processed={d} chunk_len={d} total_chunk_end={d} current_chunk_size={d} output={s} weight_route_hint={s}",
                    .{ processed, chunk.len, total_chunk_end, cursor.current_chunk_size, @tagName(output_intent), @tagName(planned_chunk.weight_route_hint) },
                );
                if (self.scheduler) |scheduler| {
                    if (self.scheduler_lease) |lease| {
                        if (self.io) |io| {
                            if (!exact_prefill_probe and !prefillFinalChunkNeedsDirectExecution(
                                total_chunk_end,
                                seq_len,
                                output_intent,
                                prefer_cuda_direct_last_logits,
                                use_metal_target_last_logits,
                            )) {
                                prefill_last_logits = self.runScheduledPrefillBatch(scheduler, lease, io, decode_state, chunk, total_chunk_end, chunk.len, total_chunk_end == seq_len, allow_shared_kv_prefill) catch |err| {
                                    if (try cursor.retryMemoryBudgetExceeded(attempt, err)) continue;
                                    return err;
                                };
                                try prompt_runtime.finishChunkState(config.kv_cache_mode == .select_v1, select_v1_gpu_oracle);
                                try cursor.commit(attempt);
                                scheduler.notePrefillProgress(lease, prefilled_tokens + cursor.processed, seq_len);
                                continue;
                            }
                        }
                    }
                }

                if (self.scheduler) |scheduler| {
                    if (self.scheduler_lease) |lease| {
                        if (self.io) |io| {
                            try scheduler.awaitTurnControlled(lease, .prefill, io, self.execution_control);
                            direct_prefill_turn_acquired = true;
                        }
                    }
                }
                var numerical = self.prefillRuntime(decode_state, directPrefillExecutionMutex(
                    exact_prefill_probe,
                    use_cuda_prefill_greedy_token or (total_chunk_end == seq_len and prefer_cuda_direct_last_logits),
                    use_metal_prefill_greedy_token,
                    self.execution_lock,
                ));
                const outcome = try numerical.runChunk(.{
                    .token_ids = chunk,
                    .total_chunk_end = total_chunk_end,
                    .prompt_tokens = seq_len,
                    .already_prefilled = prefilled_tokens,
                    .processed_rows = processed,
                    .output_intent = output_intent,
                    .capture_hidden = capture_last_hidden,
                    .shared_kv_pruning = allow_shared_kv_prefill,
                    .prepared_metal_whole_prompt = processed == 0 and total_chunk_end == seq_len and use_metal_prefill_greedy_token,
                    .metal_target_last_logits = use_metal_target_last_logits,
                    .cuda_direct_last_logits = prefer_cuda_direct_last_logits,
                    .typed_outputs = can_use_typed_prefill_outputs,
                    .attempted_chunk_size = chunk_size,
                    .allow_resize = admitted_plan == null,
                    .compact_selected = config.kv_cache_mode == .select_v1,
                    .selection_gpu_oracle = select_v1_gpu_oracle,
                    .exact_repeat_probe = exact_prefill_probe,
                    .exact_repeat_calls = &exact_prefill_calls,
                });
                switch (outcome) {
                    .retry_chunk_size => |smaller| {
                        try cursor.retry(attempt, smaller);
                        continue;
                    },
                    .complete => |output| {
                        if (output.last_logits) |values| prefill_last_logits = values;
                        if (output.greedy_token) |token| prefill_greedy_token = token;
                        if (output.last_hidden) |hidden| {
                            prefill_last_hidden = hidden;
                            prefill_last_hidden_rows = output.last_hidden_rows;
                        }
                    },
                }
                try cursor.commit(attempt);
                if (self.scheduler) |scheduler| {
                    if (self.scheduler_lease) |lease| {
                        scheduler.notePrefillProgress(lease, prefilled_tokens + cursor.processed, seq_len);
                        scheduler.finishTurn(lease, .prefill);
                        // The scoped defer is the error/continue safety net.
                        // Once the successful path releases the turn, disarm
                        // it so every chunk performs exactly one coordinator
                        // lock/unlock pair for completion.
                        direct_prefill_turn_acquired = false;
                    }
                }
            }
            try cursor.finish();
        } else {
            if (prefilled_tokens != 0) return error.UnsupportedShape;
            if (self.scheduler) |scheduler| {
                if (self.scheduler_lease) |lease| {
                    if (self.io) |io| {
                        prefill_last_logits = try self.runScheduledPrefillBatch(scheduler, lease, io, decode_state, prompt_ids, seq_len, seq_len, true, allow_shared_kv_prefill);
                        scheduler.notePrefillProgress(lease, seq_len, seq_len);
                    } else {
                        var eager_prefill = self.prefillRuntime(decode_state, null);
                        try eager_prefill.prepareWholePrompt(seq_len);
                    }
                } else {
                    var eager_prefill = self.prefillRuntime(decode_state, null);
                    try eager_prefill.prepareWholePrompt(seq_len);
                }
            } else {
                var eager_prefill = self.prefillRuntime(decode_state, null);
                try eager_prefill.prepareWholePrompt(seq_len);
            }

            if (self.scheduler) |scheduler| {
                if (self.scheduler_lease) |lease| {
                    if (self.io == null) {
                        scheduler.notePrefillProgress(lease, seq_len, seq_len);
                        scheduler.finishTurn(lease, .prefill);
                    }
                }
            }
        }

        debugGenerationStage(
            "executePrefill exit cached_logits={} greedy_token={}",
            .{ prefill_last_logits != null, prefill_greedy_token != null },
        );
        return .{
            .last_logits = prefill_last_logits,
            .greedy_token = prefill_greedy_token,
            .last_hidden = prefill_last_hidden,
            .last_hidden_rows = prefill_last_hidden_rows,
        };
    }

    fn prefillNeedsHostLogits(self: *NativeGenerationPipeline, config: GenerationConfig) bool {
        return self.prefill_logits_out != null or self.checkpoint_prepare != null or config.token_observer != null or
            config.qwen3vl_parity_json_path != null or config.qwen3vl_parity_logits_path != null or
            firstTokenTopKTraceCount() > 0 or platform.env.getenvBool("ANTFLY_INFERENCE_ATTENTION_MATCH_FIT_PROBE") or
            platform.env.getenv("TERMITE_METAL_DUMP_GENERATE_LOGITS_F32") != null or
            @import("../backends/decoder_tail_runtime.zig").repackQualityRawLogitsEnabled();
    }

    fn promptRequest(self: *NativeGenerationPipeline, config: GenerationConfig, seq_len: usize, query_tokens: usize, prefilled_tokens: usize, allow_resident_greedy_token: bool, capture_last_hidden: bool) decoder_prefill.PromptRequest {
        return .{
            .route = decoderRouteRequest(config),
            .prompt_tokens = seq_len,
            .query_tokens = query_tokens,
            .prefilled_tokens = prefilled_tokens,
            .allow_resident_greedy = allow_resident_greedy_token and !self.prefillNeedsHostLogits(config) and
                (requestSuppressionsAllowResidentGreedy(config.effectiveSuppressTokenIds(&self.gpt_config)) or
                    (self.compiled_partition_backend == .metal and self.compiled_attachment_target == .whole_model)),
            .capture_hidden = capture_last_hidden,
            .selected_kv = config.kv_cache_mode == .select_v1,
            .checkpoint = self.checkpoint_prepare != null or self.checkpoint_resume != null,
            .has_draft = self.draft_cb != null,
            .has_prompt_cache = self.prompt_cache != null,
            .scheduler_peers = if (self.scheduler) |scheduler| scheduler.shouldCoordinateCurrentRequests() else false,
            .execution_serialized = self.execution_lock != null,
            .configured_chunk_rows = config.prefill_chunk_size,
            .scheduler_chunk_rows = if (self.scheduler_lease) |lease| lease.prefill_chunk_size else 0,
            .speculative_k = config.speculative_k,
            .sampled_ring_qualified = exact_hybrid_sampled_ring_qualification_override,
        };
    }

    fn beginPreparedPrefillTurn(self: *NativeGenerationPipeline, seq_len: usize) !bool {
        const scheduler = self.scheduler orelse return false;
        const lease = self.scheduler_lease orelse return false;
        scheduler.notePrefillProgress(lease, 0, seq_len);
        const io = self.io orelse return false;
        try scheduler.awaitTurnControlled(lease, .prefill, io, self.execution_control);
        return true;
    }

    fn executePreparedMultimodalPrefill(
        self: *NativeGenerationPipeline,
        prepared: *gemma3_mm.PreparedPrompt,
        seq_len: usize,
        decode_state: *NativeDecodeState,
        capture_last_hidden: bool,
        config: GenerationConfig,
    ) !PrefillOutput {
        var numerical = self.prefillRuntime(decode_state, directPrefillExecutionMutex(true, false, false, self.execution_lock));
        const plan = try numerical.planEmbeddingPrompt(.{
            .storage = decoderStorageRequest(config),
            .query_tokens = seq_len,
            .configured_chunk_rows = config.prefill_chunk_size,
            .scheduler_chunk_rows = if (self.scheduler_lease) |lease| lease.prefill_chunk_size else 0,
            .speculative_k = config.speculative_k,
            .sampled_ring_qualified = exact_hybrid_sampled_ring_qualification_override,
        }, prepared.attn_or_mask, capture_last_hidden);
        try numerical.resetRecurrentPrompt();
        const direct_prefill_turn_acquired = try self.beginPreparedPrefillTurn(seq_len);
        defer if (direct_prefill_turn_acquired) self.scheduler.?.finishTurn(self.scheduler_lease.?, .prefill);
        if (plan.reserve_whole_prompt) try numerical.prepareWholePrompt(seq_len);

        if (prepared.input_embeddings == null) return error.InvalidPreparedPrompt;
        const logits = try numerical.runEmbeddingsOwned(.{
            .owner = &prepared.input_embeddings,
            .token_ids = prepared.ple_token_ids orelse prepared.token_ids,
            .sequence_length = seq_len,
            .output_intent = decoder_routes.prefillOutputIntent(true, !capture_last_hidden and self.draft_cb == null and decoder_routes.shouldUsePreparedPrefillGreedyToken(self.cb.kind(), self.gpt_config, decoderRouteRequest(config), true, self.prefillNeedsHostLogits(config), self.cb.kind() != .cuda or (enableCudaPrefillFirstToken() and enableCudaPrefillGreedyToken())), capture_last_hidden),
            .chunk_rows = plan.chunk_rows,
            .attention_mask = prepared.attn_or_mask,
        });
        errdefer if (logits.last_logits) |values| self.allocator.free(values);
        errdefer if (logits.last_hidden) |hidden| self.cb.free(hidden);
        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| scheduler.notePrefillProgress(lease, seq_len, seq_len);
        }
        return logits;
    }

    /// Runs prepared prompt rows through the layer stack and returns the
    /// last-row logits. Takes ownership of `input_embeddings`: the framed
    /// Metal route borrows the rows (it copies them into its own hidden
    /// buffer) and they are released here, while the generic forward
    /// consumes them, freeing them on success and on error, so ownership
    /// moves to it before that call. Only the last row feeds sampling:
    /// projecting every prompt row through the vocabulary and softcapping it
    /// on the host cost more than the layer stack for a media prompt.
    fn forwardPreparedEmbeddingsLastLogits(
        self: *NativeGenerationPipeline,
        input_embeddings: ops.CT,
        ple_token_ids: []const i64,
        seq_len: usize,
        decode_context: *const gpt_arch.DecodeContext,
        capture_last_hidden: bool,
    ) !PrefillOutput {
        var numerical = decoder_prefill.Forward{ .forward = self.physicalDecoder() };
        return numerical.forwardPreparedEmbeddingsOutput(input_embeddings, ple_token_ids, seq_len, decode_context, if (capture_last_hidden) .last_logits_and_hidden else .last_logits);
    }

    // Uniform-length pages only; the caller reserves the complete group peak.
    pub const default_prepared_qwen_prefill_items = decoder_routes.default_positioned_prefill_items;
    pub const max_prepared_qwen_prefill_items = decoder_routes.max_positioned_prefill_items;
    pub const max_prepared_qwen_prefill_rows = decoder_routes.max_positioned_prefill_rows;
    pub const packedQwenPrefillItemLimit = decoder_routes.positionedPrefillItemLimit;
    pub const preparedQwenPrefillBatchLimit = decoder_routes.positionedPrefillBatchLimit;
    pub const preparedQwenPrefillBatchLimitForBackend = decoder_routes.positionedPrefillBatchLimitForBackend;
    const preparedQwenPrefillGeometryLimit = decoder_routes.positionedPrefillGeometryLimit;

    pub const PreparedQwenPrefillItem = struct {
        pipeline: *NativeGenerationPipeline,
        prepared: *qwen3vl_projector.PreparedPrompt,
        state: *NativeDecodeState,
        seq_len: usize,
    };

    /// Group-owned CPU logits, their independent result copies, positions and
    /// bounded context metadata stay admitted until the batch forward returns.
    pub const preparedQwenPrefillHostScratch = decoder_routes.positionedPrefillHostScratch;
    pub const preparedQwenPrefillHostScratchForBackend = decoder_routes.positionedPrefillHostScratchForBackend;
    const preparedQwenPrefillHostScratchCapacity = decoder_routes.positionedPrefillHostScratchCapacity;

    /// The caller owns the shared provider step, independent page state, a
    /// complete group device envelope and the group's CPU scratch permit.
    /// No combined device tensor escapes; returned host rows are independent.
    fn positionedBatchItem(self: *NativeGenerationPipeline, prepared: *qwen3vl_projector.PreparedPrompt, state: *NativeDecodeState, seq: usize) decoder_prefill.PositionedEmbeddingBatchItem {
        return .{ .diagnostics_binding = if (self.session) |session| session.invocation_diagnostics else null, .request_id = if (self.scheduler_lease) |lease| lease.request_id else null, .allocator = self.allocator, .backend = &self.cb, .model = &self.gpt_config, .state = state, .embeddings_owner = &prepared.input_embeddings, .geometry_tokens = prepared.plan.tokenCount(), .position_ids = prepared.plan.mrope_positions, .deepstack_layer_count = prepared.deepstack_layer_count, .sequence_length = seq };
    }

    pub fn forwardPreparedQwenPrefillBatch(items: []const PreparedQwenPrefillItem) ![][]f32 {
        if (items.len > max_prepared_qwen_prefill_items) return error.InvalidBatchDecodeState;
        var requests: [max_prepared_qwen_prefill_items]decoder_prefill.PositionedEmbeddingBatchItem = undefined;
        for (items, requests[0..items.len]) |item, *request| request.* = item.pipeline.positionedBatchItem(item.prepared, item.state, item.seq_len);
        return decoder_prefill.forwardPositionedEmbeddingBatch(requests[0..items.len]);
    }

    fn executePreparedQwen3VlPrefill(
        self: *NativeGenerationPipeline,
        prepared: *qwen3vl_projector.PreparedPrompt,
        seq_len: usize,
        decode_state: *NativeDecodeState,
        wants_greedy: bool,
    ) !PrefillOutput {
        if (prepared.plan.tokenCount() != seq_len or !decode_state.isPaged()) return error.InvalidPreparedPrompt;
        // A chunk-sized epoch workspace cannot admit the direct full-prefix
        // fallback. Reject unsupported routing before cache or GPU mutation.
        if (self.prepared_qwen_prefill_chunk_rows != 0 and
            (self.qwen_prefill_batch == null or prepared.deepstack_layer_count != 0)) return error.InvalidPreparedPrompt;
        var numerical = self.prefillRuntime(decode_state, directPrefillExecutionMutex(true, false, false, self.execution_lock));
        try numerical.resetRecurrentPrompt();
        if (self.qwen_prefill_batch) |hook| if (prepared.deepstack_layer_count == 0) {
            var publication = StepPublication{ .scheduler = self.scheduler orelse return error.InvalidBatchDecodeState, .lease = self.scheduler_lease orelse return error.InvalidBatchDecodeState, .vocab_size = self.gpt_config.vocab_size };
            var request = try self.positionedRequest(prepared, decode_state, seq_len, wants_greedy, publication.interface());
            defer self.mergeStepExecutor(&request.executor);
            return hook.run_fn(hook.ptr, &request);
        };
        const direct_prefill_turn_acquired = try self.beginPreparedPrefillTurn(seq_len);
        defer if (direct_prefill_turn_acquired) self.scheduler.?.finishTurn(self.scheduler_lease.?, .prefill);
        try numerical.prepareWholePrompt(seq_len);

        if (prepared.input_embeddings == null) return error.InvalidPreparedPrompt;
        const work_trace = enableGenerationStageDebug();
        var work_complete = true;
        if (work_trace) {
            std.debug.print("native_work_prefill_dispatch: pipeline={d} route=prepared_qwen source_tokens={d} cached_prefix=0 query_tokens={d}\n", .{ @intFromPtr(self), seq_len, prepared.token_ids.len });
            debugNativeWorkIds(@intFromPtr(self), "dispatch_query", prepared.token_ids);
        }
        defer if (work_trace) {
            std.debug.print("native_work_prefill_result: pipeline={d} route=prepared_qwen completed={} query_tokens={d}\n", .{ @intFromPtr(self), work_complete, prepared.token_ids.len });
        };
        errdefer work_complete = false;
        const output = try numerical.runEmbeddingsOwned(.{
            .owner = &prepared.input_embeddings,
            .token_ids = prepared.token_ids,
            .sequence_length = seq_len,
            .ensure_device_resident = false,
            .route = .ordinary_last_row,
            .positions = prepared.plan.mrope_positions,
            .visual_mask = prepared.plan.visual_token_mask,
            .deepstack_embeddings = prepared.deepstack_embeddings,
            .deepstack_layer_count = prepared.deepstack_layer_count,
        });
        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| scheduler.notePrefillProgress(lease, seq_len, seq_len);
        }
        return output;
    }

    const DecodeResult = struct {
        tokens_generated: usize,
        finish_reason: []const u8,
        /// Accepted output tokens which have not yet been consumed by a
        /// following model forward and therefore have no materialized KV row.
        pending_unmaterialized_tokens: u8 = 0,
        prompt_lookup: prompt_lookup.Counters = .{},
    };

    const DeviceDecodeOutcome = decoder_forward.DeviceTokenOutcome;

    fn noteDecodeProgressNoMicrobatch(self: *NativeGenerationPipeline, tokens_generated: usize) void {
        if (self.failure_trace) |trace| trace.decoded_tokens = tokens_generated;
        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| {
                scheduler.noteDecodeProgress(lease, tokens_generated);
                scheduler.finishTurn(lease, .decode);
            }
        }
    }

    fn resolveFinalChannelEndTokenId(self: *NativeGenerationPipeline) !?i32 {
        if (!self.gpt_config.usesGemma4Channels()) return null;
        return resolveTokenId(self.tokenizer, self.allocator, "<channel|>");
    }

    fn resolveFinalChannelHeaderTokenIds(
        self: *NativeGenerationPipeline,
        final_channel_end_token_id: i32,
    ) !?[]i32 {
        const ids = try self.tokenizer.encode(
            self.allocator,
            "<|channel>final\n<channel|>",
        );
        errdefer self.allocator.free(ids);
        if (ids.len == 0 or ids[ids.len - 1] != final_channel_end_token_id) {
            self.allocator.free(ids);
            return null;
        }
        return ids;
    }

    fn resolveChannelStartTokenId(self: *NativeGenerationPipeline) !?i32 {
        return resolveTokenId(self.tokenizer, self.allocator, "<|channel>");
    }

    fn resolveTurnEndTokenId(self: *NativeGenerationPipeline) !?i32 {
        if (!self.gpt_config.usesGemma4Channels()) return null;
        return resolveTokenId(self.tokenizer, self.allocator, "<turn|>");
    }

    fn emitDecodedDelta(
        self: *NativeGenerationPipeline,
        generated_token_ids: []const i64,
        state: *StreamingTextState,
        on_token_fn: TokenCallback,
        on_token_ctx: *anyopaque,
    ) !bool {
        if (self.continue_fn) |should_continue| {
            const continue_ctx = self.continue_ctx orelse return error.InvalidCallbackContext;
            if (!should_continue(continue_ctx)) return false;
        }
        return emitDecodedDeltaForTokenizer(
            self.tokenizer,
            self.allocator,
            generated_token_ids,
            state,
            on_token_fn,
            on_token_ctx,
        );
    }

    fn tryReturnPrefillFirstToken(
        self: *NativeGenerationPipeline,
        token_ids: []i64,
        seq_len: *usize,
        config: GenerationConfig,
        prefill_last_logits: *?[]f32,
        prefill_greedy_token: *?usize,
        penalty_state: *SamplingPenaltyState,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*grammar_mod.GbnfGrammar,
        max_tokens: usize,
        prompt_token_count: usize,
        on_token_fn: ?TokenCallback,
        on_token_ctx: ?*anyopaque,
        emitted_text: ?*StreamingTextState,
        work_trace: bool,
    ) !?DecodeResult {
        if (!shouldUsePrefillFirstTokenPath(
            self.cb.kind(),
            isPureGreedyConfig(config) and config.grammar == null,
            false,
            enableCudaPrefillFirstToken(),
        )) {
            debugFirstToken(
                "prefill_first_token disabled backend={s} max_tokens={d} pure_greedy={} enabled={}",
                .{ @tagName(self.cb.kind()), max_tokens, isPureGreedyConfig(config), enableCudaPrefillFirstToken() },
            );
            return null;
        }

        const has_grammar = json_grammar.* != null or gbnf_grammar != null;
        const outcome: SampleOutcome = blk: {
            if (!has_grammar) {
                if (prefill_greedy_token.*) |token| {
                    prefill_greedy_token.* = null;
                    debugFirstToken("prefill_first_token source=greedy token={d}", .{token});
                    break :blk .{ .token = token, .grammar_complete = false };
                }
            }
            if (prefill_last_logits.*) |cached_logits| {
                debugFirstToken(
                    "prefill_first_token source=logits len={d} grammar={}",
                    .{ cached_logits.len, has_grammar },
                );
                try self.debugFirstTokenTopLogits("first_token_top_logits_raw", cached_logits);
                const suppress_token_ids = config.effectiveSuppressTokenIds(&self.gpt_config);
                if (suppress_token_ids.len > 0 and firstTokenTopKTraceCount() > 0) {
                    const masked_logits = try self.allocator.dupe(f32, cached_logits);
                    defer self.allocator.free(masked_logits);
                    applySuppressTokenMask(masked_logits, suppress_token_ids);
                    try self.debugFirstTokenTopLogits("first_token_top_logits_post_suppress", masked_logits);
                }
                break :blk try self.sampleNextToken(
                    cached_logits,
                    config,
                    penalty_state,
                    token_table,
                    json_grammar,
                    gbnf_grammar,
                );
            }
            debugFirstToken(
                "prefill_first_token unavailable greedy={} logits={} grammar={}",
                .{ prefill_greedy_token.* != null, prefill_last_logits.* != null, has_grammar },
            );
            return null;
        };

        const next_token = outcome.token;
        if (self.shouldStopOnEos(config, next_token, work_trace)) {
            self.finishPrefillFirstTokenSchedulerTurn(0);
            debugFirstToken("prefill_first_token eos token={d}", .{next_token});
            return .{ .tokens_generated = 0, .finish_reason = "stop" };
        }

        token_ids[seq_len.*] = @intCast(next_token);
        seq_len.* += 1;
        try penalty_state.noteToken(self.allocator, @intCast(next_token));

        var finish_reason: []const u8 = "length";
        if (on_token_fn != null and on_token_ctx != null and emitted_text != null) {
            const keep_streaming = try self.emitDecodedDelta(
                token_ids[prompt_token_count..seq_len.*],
                emitted_text.?,
                on_token_fn.?,
                on_token_ctx.?,
            );
            if (!keep_streaming) finish_reason = "stop";
        }
        if (outcome.grammar_complete) finish_reason = "stop";

        self.finishPrefillFirstTokenSchedulerTurn(1);
        debugFirstToken(
            "prefill_first_token returned token={d} seq_len={d} finish_reason={s}",
            .{ next_token, seq_len.*, finish_reason },
        );
        return .{
            .tokens_generated = 1,
            .finish_reason = finish_reason,
            .pending_unmaterialized_tokens = 1,
        };
    }

    fn finishPrefillFirstTokenSchedulerTurn(self: *NativeGenerationPipeline, tokens_generated: usize) void {
        if (self.scheduler) |scheduler| {
            if (self.scheduler_lease) |lease| {
                scheduler.noteDecodeProgress(lease, tokens_generated);
                scheduler.finishTurn(lease, .decode);
            }
        }
    }

    const FirstTokenTopLogit = struct {
        id: usize,
        logit: f32,
    };

    fn debugFirstTokenTopLogits(self: *NativeGenerationPipeline, label: []const u8, logits: []const f32) !void {
        const requested = firstTokenTopKTraceCount();
        if (requested == 0) return;
        const count = @min(requested, logits.len);
        var entries = try self.allocator.alloc(FirstTokenTopLogit, logits.len);
        defer self.allocator.free(entries);
        for (logits, 0..) |logit, idx| entries[idx] = .{ .id = idx, .logit = logit };
        std.mem.sort(FirstTokenTopLogit, entries, {}, struct {
            fn lessThan(_: void, lhs: FirstTokenTopLogit, rhs: FirstTokenTopLogit) bool {
                return lhs.logit > rhs.logit;
            }
        }.lessThan);

        std.debug.print("{s}:\n", .{label});
        for (entries[0..count], 0..) |entry, rank| {
            const token_id: i32 = @intCast(entry.id);
            const decoded = self.tokenizer.decode(self.allocator, &.{token_id}) catch |err| {
                std.debug.print("  rank={d} id={d} logit={d:.6} text=<decode_error:{s}>\n", .{
                    rank + 1,
                    entry.id,
                    entry.logit,
                    @errorName(err),
                });
                continue;
            };
            defer self.allocator.free(decoded);
            std.debug.print("  rank={d} id={d} logit={d:.6} text={s}\n", .{ rank + 1, entry.id, entry.logit, decoded });
        }
    }

    /// Standard autoregressive decode loop: generate one token at a time
    /// with grammar masking, sampling, and scheduler coordination.
    fn metalQualificationOwnerSnapshot(
        state: *const NativeDecodeState,
        phase: []const u8,
        require_inner: bool,
        tracker: *runtime.kv.host_allocation_tracker.HostAllocationTracker,
    ) !runtime.kv.host_allocation_tracker.Snapshot {
        const current = tracker.snapshot();
        if (!std.mem.eql(u8, phase, "generation_committed")) return current;
        if (state.last_context_owner_committed) |committed| {
            if (!committed.available or committed.owner_identity == 0 or
                committed.owner_identity != current.owner_identity or
                !committed.physical_available or
                !committed.tracked_combined_physical_available)
                return error.ContextPhysicalAccountingUnavailable;
            return committed;
        }
        if (require_inner) return error.ContextPhysicalAccountingUnavailable;
        return current;
    }

    fn isFreshCompiledOwnerSnapshotBoundary(state: *const NativeDecodeState, phase: []const u8) bool {
        return std.mem.eql(u8, phase, "prefill_started") and state.total_tokens == 0 and
            state.context_session == null and state.last_context_owner_committed == null and
            !state.last_context_session_released and !state.last_context_session_allocation_start.available and
            !state.last_context_session_allocation_end.available;
    }

    /// Resolve the request-owned compiled participant before any outer Metal
    /// queue is synchronized. Rejected or cancelled requests must not mutate a
    /// cached runtime or GPU state. A fresh prefill may retire only an unbound
    /// mutable session; GraphCache entries and their immutable executors remain.
    fn prepareCompiledOwnerSnapshot(
        binding: ?graph_mod.model_runtime.ContextOwnerBinding,
        cache: ?*graph_mod.cache.GraphCache,
        control: ?InferenceExecutionControl,
        state: *const NativeDecodeState,
        phase: []const u8,
    ) !void {
        if (control) |request_control| try request_control.check();
        if (binding) |expected| {
            try expected.validate();
            const compiled_state = try expected.owner.compiledStorageState(expected.witness);
            const compiled_runtime = if (cache) |available| available.getSessionCompiledModelRuntime(.metal, .whole_model) else null;
            switch (compiled_state) {
                .not_required => if (compiled_runtime != null) return error.ContextFrameOwnershipMismatch,
                .required_unbound => {
                    if (!isFreshCompiledOwnerSnapshotBoundary(state, phase))
                        return error.ContextPhysicalAccountingUnavailable;
                    if (compiled_runtime) |cached| {
                        if (try cached.contextOwnerBindingState(expected) != .unbound)
                            return error.ContextFrameOwnershipMismatch;
                        const available = cache orelse unreachable;
                        available.resetSessionCompiledModelRuntime();
                        if (available.getSessionCompiledModelRuntime(.metal, .whole_model) != null)
                            return error.CompiledModelRuntimeRetirementFailed;
                    }
                },
                .bound_live => {
                    const live = compiled_runtime orelse return error.MissingCompiledModelRuntime;
                    if (try live.contextOwnerBindingState(expected) != .exact)
                        return error.ContextFrameOwnershipMismatch;
                    try live.drainContextOwnerSnapshot(expected);
                },
                .detached => if (compiled_runtime != null) return error.ContextFrameOwnershipMismatch,
            }
        } else if (cache) |available| {
            if (available.getSessionCompiledModelRuntime(.metal, .whole_model) != null)
                return error.ContextPhysicalAccountingUnavailable;
        }
    }

    fn validateAttentionMatchRepeatAuthority(options: AttentionMatchQueryOptions) !void {
        if (options.owner_component_diagnostic_request != 0 and
            (options.prefix_mode != .clone or options.repeat_mode != .reference or options.stats == null))
            return error.UnsupportedCompactionQueryRoute;
        if (options.study_pass != 0 and (!builtin.is_test or !options.representative_repeat))
            return error.UnsupportedCompactionQueryRoute;
        runtime.kv.attention_match_self_study_training.validateExplicitRepeatBinding(
            options.explicit_repeat_tokens != null,
            options.representative_repeat,
            options.study_pass,
            options.explicit_repeat_sha256 != null,
        ) catch return error.UnsupportedCompactionQueryRoute;
        if (options.explicit_sample_offsets != null and
            (options.explicit_repeat_tokens == null or options.representative_repeat or options.study_pass != 0))
            return error.UnsupportedCompactionQueryRoute;
    }

    fn dense512QueryOptions(
        repeat_tokens: []const i64,
        repeat_sha256: [32]u8,
        offsets: []const u32,
        stats: *AttentionMatchQueryStats,
    ) AttentionMatchQueryOptions {
        return .{
            .prefix_mode = .clone,
            .repeat_mode = .reference,
            .collection = .{ .samples_per_consumer = runtime.kv.attention_match_reference_coverage.dense512_sample_count, .max_bytes = 80 * 1024 * 1024 },
            .chunk_size = 256,
            .max_repeat_tokens = NativeCheckpointPrepare.max_repeat_tokens,
            .representative_repeat = false,
            .explicit_repeat_tokens = repeat_tokens,
            .explicit_repeat_sha256 = repeat_sha256,
            .explicit_sample_offsets = offsets,
            .stats = stats,
        };
    }

    fn admitNativeQualityPhase(
        plan: @import("../runtime/kv/metal_checkpoint_cycles.zig").PhasePlan,
        retained_wire_bytes: usize,
    ) !usize {
        var charged = plan;
        charged.wire = try std.math.add(usize, charged.wire, retained_wire_bytes);
        return charged.admit() catch |err| {
            if (builtin.is_test and platform.env.getenvBool("ANTFLY_METAL_CHECKPOINT_FIT_PROFILE"))
                std.debug.print("native_quality_admission_rejected owners={d} host={d} queries={d} wire={d} import={d} device={d}\n", .{ charged.owners, charged.host, charged.queries, charged.wire, charged.import, charged.device });
            return err;
        };
    }

    const MetalQualityCandidateSource = union(enum) {
        fit: ?*const PreparedCompactionStudy,
        supplied: @import("../runtime/kv/metal_checkpoint_quality.zig").SuppliedCandidate,
        prepared_serving: *@import("../runtime/kv/metal_checkpoint_quality.zig").PreparedServingCandidate,

        fn runsFit(self: MetalQualityCandidateSource) bool {
            return switch (self) {
                .fit => true,
                .supplied => false,
                .prepared_serving => false,
            };
        }

        fn usesRetainedSource(self: MetalQualityCandidateSource) bool {
            return switch (self) {
                .prepared_serving => true,
                else => false,
            };
        }

        fn retainedInputBytes(self: MetalQualityCandidateSource) usize {
            return switch (self) {
                .prepared_serving => |prepared| prepared.retained_input_bytes,
                else => 0,
            };
        }

        fn runFitFactory(self: MetalQualityCandidateSource, context: anytype, factory: anytype) !?NativeCheckpointPrepare.HostPlan {
            return switch (self) {
                .fit => try factory(context),
                .supplied => null,
                .prepared_serving => null,
            };
        }
    };
    fn standardDecode(
        self: *NativeGenerationPipeline,
        token_ids: []i64,
        seq_len: *usize,
        decode_state: *NativeDecodeState,
        storage_request: *const decoder_storage.SelectedRequest,
        config: GenerationConfig,
        prefill_last_logits: *?[]f32,
        prefill_greedy_token: *?usize,
        penalty_state: *SamplingPenaltyState,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*grammar_mod.GbnfGrammar,
        initial_tokens_generated: usize,
        max_tokens: usize,
        prompt_token_count: usize,
        on_token_fn: ?TokenCallback,
        on_token_ctx: ?*anyopaque,
        emitted_text: ?*StreamingTextState,
        work_trace: bool,
    ) !DecodeResult {
        const allocator = self.allocator;
        var decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);
        var tokens_generated = initial_tokens_generated;
        var kv_boundary = AutoregressiveKvBoundary.init(initial_tokens_generated > 0);
        var finish_reason: []const u8 = "length";
        var prompt_lookup_proposer = if (promptLookupRequestEligible(
            getenvBool("ANTFLY_INFERENCE_PROMPT_LOOKUP"),
            self.draft_cb != null,
            false,
            config.grammar != null or config.token_observer != null,
            isPureGreedyConfig(config),
            config.context_policy.mode == .exact,
            supportsSpeculativeTargetVerification(self.cb.kind(), self.gpt_config),
            self.scheduler == null and self.executor_sequence_control == null,
            decode_state.context_session == null and decode_state.isPaged() and config.kv_cache_mode == .exact_hybrid,
        )) try prompt_lookup.Proposer.init(.{ .max_draft = 1 }) else null;
        var device_token = self.deviceTokenOwner();
        defer device_token.clear();
        debugGenerationStage(
            "standardDecode enter seq_len={d} max_tokens={d} prefill_cached={}",
            .{ seq_len.*, max_tokens, prefill_last_logits.* != null },
        );
        if (initial_tokens_generated == 0 and self.execution_lock == null) {
            if (try self.standardDecodeCudaPendingTokenReadback(
                token_ids,
                seq_len,
                decode_state,
                config,
                prefill_last_logits,
                prefill_greedy_token,
                penalty_state,
                token_table,
                json_grammar,
                gbnf_grammar,
                max_tokens,
                prompt_token_count,
                on_token_fn,
                on_token_ctx,
                emitted_text,
                work_trace,
            )) |pending_result| {
                return pending_result;
            }
        }

        while (tokens_generated < max_tokens) {
            if (self.failure_trace) |trace| trace.decoded_tokens = tokens_generated;
            // One direct-step sample includes a declined device fast path and
            // its fallback, excluding scheduler waits and scheduled dispatch.
            var direct_ns: u64 = 0;
            var direct_attempted = false;
            defer if (direct_attempted) @import("antfly_readers").pipeline_metrics.observe(.decode, direct_ns);
            if (self.execution_control) |control| try control.update(.executing, @intCast(tokens_generated), @intCast(max_tokens));
            if (tokens_generated > 0) {
                if (prompt_lookup_proposer) |*proposer| {
                    const remaining = max_tokens - tokens_generated;
                    var proposal_buffer: [16]i64 = undefined;
                    const proposal = try proposer.propose(token_ids[0..seq_len.*], remaining, &proposal_buffer);
                    if (self.execution_control) |control| try control.update(.executing, @intCast(tokens_generated), @intCast(max_tokens));
                    if (proposal.tokens.len > 0) {
                        // Verification consumes the currently pending sample
                        // through the host q_len=2 input. A retained device
                        // handoff for that same sample would be stale afterward.
                        device_token.clear();
                        const result = try self.verifyPromptLookupProposal(
                            token_ids,
                            seq_len,
                            decode_state,
                            config,
                            proposal.tokens,
                            remaining,
                            penalty_state,
                        );
                        proposer.noteVerification(result.drafted, result.matched_drafts, result.drafted + 1);
                        tokens_generated += result.accepted;
                        if (result.pending_unmaterialized_tokens == 0)
                            kv_boundary.noteForwardConsumedSample()
                        else
                            kv_boundary.noteAcceptedSample();
                        if (on_token_fn != null and on_token_ctx != null and emitted_text != null) {
                            const keep_streaming = try self.emitDecodedDelta(
                                token_ids[prompt_token_count..seq_len.*],
                                emitted_text.?,
                                on_token_fn.?,
                                on_token_ctx.?,
                            );
                            if (!keep_streaming) {
                                finish_reason = "stop";
                                break;
                            }
                        }
                        if (result.hit_eos or result.hit_grammar_stop) {
                            finish_reason = "stop";
                            break;
                        }
                        if (result.accepted == 0) return error.InvalidSpeculativeState;
                        continue;
                    }
                }
            }
            if (tokens_generated > 0 and self.executor_sequence_control != null and
                !config.fixed_length_mask_eos and
                self.gpt_config.hasQwen35VisionArchitectureContract() and (self.cb.kind() == .metal or self.cb.kind() == .cuda) and
                self.execution_lock != null and self.io != null and self.scheduler_lease != null and
                self.scheduler != null and self.scheduler.?.hasExecutor() and self.scheduler.?.usesStepEvents() and
                isPureGreedyConfig(config) and !penalty_state.enabled and
                token_table == null and json_grammar.* == null and gbnf_grammar == null and
                on_token_fn == null and on_token_ctx == null and
                self.executor_sequence_control.?.progress == null and
                (self.execution_control == null or self.execution_control.?.progress == null))
            {
                return self.runExecutorGreedyTail(token_ids, seq_len, decode_state, config, tokens_generated, max_tokens, work_trace);
            }
            var used_decode_microbatch = false;
            var direct_decode_turn_acquired = false;
            defer if (direct_decode_turn_acquired) {
                self.scheduler.?.finishTurn(self.scheduler_lease.?, .decode);
            };
            var next_device_token = self.deviceTokenOwner();
            defer next_device_token.clear();
            debugGenerationStage(
                "standardDecode iter={d} seq_len={d} device_token_handoff={}",
                .{ tokens_generated, seq_len.*, device_token.tensor != null },
            );
            if (tokens_generated > 0 and prompt_lookup_proposer == null and
                self.pipelinedGreedyEligible(config, token_table, json_grammar, gbnf_grammar, decode_state))
            {
                if (try self.runPipelinedGreedyTail(
                    token_ids,
                    seq_len,
                    decode_state,
                    config,
                    penalty_state,
                    max_tokens,
                    prompt_token_count,
                    on_token_fn,
                    on_token_ctx,
                    emitted_text,
                    &tokens_generated,
                    &finish_reason,
                    work_trace,
                )) {
                    break;
                }
            }
            var sampled_without_forward = false;
            const outcome: SampleOutcome = blk: {
                if (tokens_generated == 0) {
                    if (prefill_greedy_token.*) |token| {
                        prefill_greedy_token.* = null;
                        sampled_without_forward = true;
                        break :blk .{ .token = token, .grammar_complete = false };
                    }
                }

                const has_cached_prefill_logits = tokens_generated == 0 and prefill_last_logits.* != null;
                // Once a second request is admitted inside the validated C2
                // envelope, keep both requests on the scheduler path. A
                // compatibility-only check here races with the later
                // enqueue/turn acquisition: one request can commit to a
                // direct step while its peer observes the old decode position
                // and waits for work that will never be enqueued. The
                // scheduler still admits only full-geometry-compatible work,
                // and incompatible peers do not pay a coalescing delay.
                const route_decode_through_scheduler = !config.fixed_length_mask_eos and self.execution_lock != null and self.scheduler_lease != null and
                    (self.cb.execution_owner != 0 or (if (self.scheduler) |scheduler| scheduler.shouldCoordinateCurrentRequests() else false));
                // A cooperative CUDA request uses the same canonical logits
                // path while alone and shared. Admission/retirement of a peer
                // must not switch its numerical policy mid-generation.
                if (route_decode_through_scheduler and self.cb.kind() == .metal and
                    isPureGreedyConfig(config) and token_table == null and json_grammar.* == null and gbnf_grammar == null and
                    !has_cached_prefill_logits)
                {
                    const scheduled = try self.runScheduledDecodeBatch(self.scheduler.?, self.scheduler_lease.?, self.io.?, decode_state, token_ids[seq_len.* - 1], seq_len.*, true, config.effectiveSuppressTokenIds(&self.gpt_config));
                    break :blk .{ .token = scheduled.token orelse return error.InvalidBatchDecodeState, .grammar_complete = false };
                }
                const allow_direct_device_decode = !route_decode_through_scheduler;
                if (!has_cached_prefill_logits and allow_direct_device_decode and self.compiled_media_prefix == null) {
                    const direct_token = direct_token_blk: {
                        // Above the batching rollout cap the scheduler emits
                        // singleton work, but direct device decode must still
                        // claim its fair turn before taking the shared model.
                        if (self.execution_lock != null) {
                            if (self.scheduler) |scheduler| {
                                if (self.scheduler_lease) |lease| {
                                    if (self.io) |io| {
                                        try scheduler.awaitTurnControlled(lease, .decode, io, self.execution_control);
                                        direct_decode_turn_acquired = true;
                                    }
                                }
                            }
                        }
                        var execution_scope = if (self.execution_lock) |mutex| try self.lockExecution(mutex) else null;
                        defer if (execution_scope) |*scope| scope.deinit();
                        const phase_timer = @import("antfly_readers").pipeline_metrics.start(.decode);
                        direct_attempted = true;
                        defer direct_ns +|= platform.time.monotonicNs() -| phase_timer.started_ns;
                        break :direct_token_blk try self.forwardGreedyDeviceDecodeToken(
                            token_ids,
                            seq_len.*,
                            tokens_generated,
                            decode_state,
                            config,
                            penalty_state,
                            token_table,
                            json_grammar,
                            gbnf_grammar,
                            device_token.tensor,
                        );
                    };
                    if (direct_token) |token| {
                        next_device_token.replace(token.token_tensor);
                        break :blk .{ .token = token.token, .grammar_complete = false };
                    }
                    const fallback_query_seq_len = if (decode_state.hasRetainedAttention() and
                        (tokens_generated > 0 or prefill_last_logits.* == null)) 1 else seq_len.*;
                    if (requiresCudaDecodeGraphBeforeEagerFallback(
                        self.cb.kind(),
                        gpt_arch.cudaDecodeGraphReplayRequired(),
                        isPureGreedyConfig(config),
                        fallback_query_seq_len,
                        self.graph_cache != null or self.compiled_partition_backend != null,
                        token_table != null or json_grammar.* != null or gbnf_grammar != null,
                    )) return error.CudaGraphReplayRequired;
                }

                var owns_last_logits = false;
                const last_logits: []const f32 = logits_blk: {
                    if (tokens_generated == 0) {
                        if (prefill_last_logits.*) |cached| {
                            sampled_without_forward = true;
                            debugGenerationStage(
                                "standardDecode iter={d} using cached prefill logits len={d}",
                                .{ tokens_generated, cached.len },
                            );
                            break :logits_blk cached;
                        }
                    }

                    if (self.compiled_decoder) |decoder| {
                        owns_last_logits = true;
                        break :logits_blk try decoder.text(token_ids[0..seq_len.*], self.allocator, self.execution_control);
                    }
                    if (self.compiled_media_prefix) |prefix| {
                        owns_last_logits = true;
                        break :logits_blk try prefix.run(self.session.?, token_ids[0..seq_len.*], self.allocator, self.execution_control);
                    }

                    if (self.scheduler) |scheduler| {
                        if (self.scheduler_lease) |lease| {
                            if (self.io) |io| {
                                if (!config.fixed_length_mask_eos and self.graph_cache == null and decode_runtime.kvView() != null and (tokens_generated > 0 or prefill_last_logits.* == null)) {
                                    used_decode_microbatch = true;
                                    owns_last_logits = true;
                                    break :logits_blk (try self.runScheduledDecodeBatch(scheduler, lease, io, decode_state, token_ids[seq_len.* - 1], seq_len.*, false, config.effectiveSuppressTokenIds(&self.gpt_config))).logits.?;
                                }
                                try scheduler.awaitTurnControlled(lease, .decode, io, self.execution_control);
                                direct_decode_turn_acquired = true;
                            }
                        }
                    }

                    const phase_timer = @import("antfly_readers").pipeline_metrics.start(.decode);
                    direct_attempted = true;
                    defer direct_ns +|= platform.time.monotonicNs() -| phase_timer.started_ns;
                    const pure_greedy = isPureGreedyConfig(config);
                    const selected_kv = config.kv_cache_mode == .select_v1;
                    const has_grammar = token_table != null or json_grammar.* != null or gbnf_grammar != null;
                    const sampled_compiled = !selected_kv and !pure_greedy;
                    var numerical = self.physicalDecoder();
                    switch (try numerical.eagerStep(decode_state, .{
                        .token_history = token_ids[0..seq_len.*],
                        .sequence_length = seq_len.*,
                        .generated_tokens = tokens_generated,
                        .has_prefill_logits = prefill_last_logits.* != null,
                        .compiled_sampling = if (sampled_compiled) .{
                            .temperature = config.temperature,
                            .top_p = config.top_p,
                            .top_k = config.top_k,
                            .min_p = config.min_p,
                            .repetition_penalty = config.repetition_penalty,
                            .frequency_penalty = config.frequency_penalty,
                            .presence_penalty = config.presence_penalty,
                        } else null,
                        .compiled_sampling_eligible = sampled_compiled and compiledSampleRequestEligible(config, has_grammar, self.gpt_config.suppressTokenIds().len != 0),
                        .compiled_greedy_eligible = !selected_kv and pure_greedy and !has_grammar and config.grammar == null,
                        .suppress_token_ids = config.effectiveSuppressTokenIds(&self.gpt_config),
                        .prefetch_drain_budget = prefetch_drain_budget_per_step,
                        .continuation = if (self.compiled_partition_backend == .metal and self.compiled_attachment_target == .whole_model)
                            decodeContinuation(&self.gpt_config, config, max_tokens - tokens_generated)
                        else
                            null,
                    })) {
                        .token => |token| break :blk .{ .token = token, .grammar_complete = false },
                        .logits => |logits| {
                            owns_last_logits = true;
                            break :logits_blk logits;
                        },
                    }
                };

                defer if (owns_last_logits) allocator.free(@constCast(last_logits));
                debugGenerationStage(
                    "standardDecode iter={d} logits ready len={d} owns={}",
                    .{ tokens_generated, last_logits.len, owns_last_logits },
                );

                break :blk try self.sampleNextToken(
                    last_logits,
                    config,
                    penalty_state,
                    token_table,
                    json_grammar,
                    gbnf_grammar,
                );
            };
            const next_token = outcome.token;
            if (!sampled_without_forward) kv_boundary.noteForwardConsumedSample();
            debugGenerationStage(
                "standardDecode iter={d} sampled next_token={d} grammar_complete={}",
                .{ tokens_generated, next_token, outcome.grammar_complete },
            );

            // Check EOS
            if (self.shouldStopOnEos(config, next_token, work_trace)) {
                finish_reason = "stop";
                break;
            }

            if (next_device_token.tensor == null and self.shouldSeedDeviceTokenHandoff(tokens_generated, decode_state, config, token_table, json_grammar, gbnf_grammar)) {
                try next_device_token.seed(next_token);
                decoder_runtime_debug_stats.device_token_handoff_seeds += 1;
            }
            device_token.replace(next_device_token.take());

            token_ids[seq_len.*] = @intCast(next_token);
            seq_len.* += 1;
            tokens_generated += 1;
            _ = try storage_request.commitGeneratedToken(&decode_runtime, .{
                .allow_metadata_scope = self.prompt_cache != null and self.cb.execution_batch_drain != null and
                    platform.env.getenvBoolDefault("ANTFLY_INFERENCE_CUDA_KV_METADATA_SCOPE", true),
                .execution = if (self.execution_lock) |mutex| self.executionAccess(mutex) else .{ .io = self.io, .control = self.execution_control },
                .cleanup_owner = self.execution_cleanup_owner,
                .backend = &self.cb,
            });
            try penalty_state.noteToken(allocator, @intCast(next_token));
            debugGenerationStage(
                "standardDecode iter={d} appended token new_seq_len={d}",
                .{ tokens_generated, seq_len.* },
            );
            if (on_token_fn != null and on_token_ctx != null and emitted_text != null) {
                const keep_streaming = try self.emitDecodedDelta(
                    token_ids[prompt_token_count..seq_len.*],
                    emitted_text.?,
                    on_token_fn.?,
                    on_token_ctx.?,
                );
                if (!keep_streaming) {
                    finish_reason = "stop";
                    break;
                }
            }
            if (outcome.grammar_complete) {
                finish_reason = "stop";
                break;
            }
            if (self.scheduler) |scheduler| {
                if (self.scheduler_lease) |lease| {
                    scheduler.noteDecodeProgress(lease, tokens_generated);
                    if (!used_decode_microbatch) {
                        scheduler.finishTurn(lease, .decode);
                    }
                }
            }
        }

        debugGenerationStage(
            "standardDecode exit tokens_generated={d} finish_reason={s}",
            .{ tokens_generated, finish_reason },
        );
        return .{
            .tokens_generated = tokens_generated,
            .finish_reason = finish_reason,
            .pending_unmaterialized_tokens = kv_boundary.pending_unmaterialized_tokens,
            .prompt_lookup = if (prompt_lookup_proposer) |proposer| proposer.counters else .{},
        };
    }

    fn pipelinedGreedyEligible(
        self: *NativeGenerationPipeline,
        config: GenerationConfig,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *const ?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*const grammar_mod.GbnfGrammar,
        decode_state: *NativeDecodeState,
    ) bool {
        if (config.fixed_length_mask_eos) return false;
        if (config.kv_cache_mode == .select_v1) return false;
        if (!pipelinedMetalDecodeEnabled()) return false;
        var decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);
        if (self.cb.kind() != .metal) return false;
        if (self.scheduler != null) return false;
        if (self.graph_cache != null or self.compiled_partition_backend != null) return false;
        if (decode_runtime.kvView() == null) return false;
        if (!isPureGreedyConfig(config)) return false;
        if (token_table != null or json_grammar.* != null or gbnf_grammar != null) return false;
        if (self.gpt_config.family != .gemma or !self.gpt_config.hasPle()) return false;
        if (!gemma4MetalDirectGreedyEnabled()) return false;
        return true;
    }

    fn pendingStepContext(self: *NativeGenerationPipeline, state: *NativeDecodeState) pending_step.Context {
        return .{
            .observation = @import("../execution/pending_observation.zig").Source.fromSession(self.session, if (self.scheduler_lease) |lease| lease.request_id else null),
            .allocator = self.allocator,
            .backend = &self.cb,
            .model = &self.gpt_config,
            .state = state,
            .control = self.execution_control,
            .execution = if (self.execution_lock) |mutex| self.executionAccess(mutex) else .{ .io = self.io, .control = self.execution_control },
            .prefetch_drain_budget = prefetch_drain_budget_per_step,
        };
    }

    fn runPipelinedGreedyTail(
        self: *NativeGenerationPipeline,
        token_ids: []i64,
        seq_len: *usize,
        decode_state: *NativeDecodeState,
        config: GenerationConfig,
        penalty_state: *SamplingPenaltyState,
        max_tokens: usize,
        prompt_token_count: usize,
        on_token_fn: ?TokenCallback,
        on_token_ctx: ?*anyopaque,
        emitted_text: ?*StreamingTextState,
        tokens_generated: *usize,
        finish_reason: *[]const u8,
        work_trace: bool,
    ) !bool {
        if (tokens_generated.* >= max_tokens) return false;
        if (seq_len.* == 0) return false;
        var pending = try pending_step.GreedyFrame.init(self.pendingStepContext(decode_state));
        defer pending.deinit();
        pending.drainPrefetch();
        // A driver error may follow a committed submission. Cleanup owns the
        // lane until cancel/drain complete; only explicit false can decline.
        errdefer pending.abort();
        if (!try pending.arm(token_ids[seq_len.* - 1], seq_len.*)) return false;
        while (tokens_generated.* < max_tokens) {
            if (self.execution_control) |control| try control.update(.executing, @intCast(tokens_generated.*), @intCast(max_tokens));
            const remaining = max_tokens - tokens_generated.*;
            var next_token: i64 = -1;
            var stepped = false;
            if (remaining > 1) {
                _ = try pending.reserveLookahead();
                if (try pending.step(seq_len.* + 1)) |tok| {
                    next_token = tok;
                    stepped = true;
                } else {
                    next_token = (try pending.awaitToken()) orelse return error.InvalidModelOutput;
                }
            } else {
                next_token = (try pending.awaitToken()) orelse return error.InvalidModelOutput;
            }
            if (next_token < 0) return error.InvalidModelOutput;
            const token: usize = @intCast(next_token);
            if (self.shouldStopOnEos(config, token, work_trace)) {
                if (stepped) {
                    pending.cancelPending();
                }
                finish_reason.* = "stop";
                return true;
            }
            if (stepped) {
                const submit_ok = try pending.submit();
                if (!submit_ok) {
                    pending.cancelPending();
                    stepped = false;
                }
            }
            token_ids[seq_len.*] = @intCast(token);
            seq_len.* += 1;
            tokens_generated.* += 1;
            if (!pending.reserved_position) _ = try pending.reserveLookahead();
            try pending.commitPosition();
            try penalty_state.noteToken(self.allocator, @intCast(token));
            if (on_token_fn != null and on_token_ctx != null and emitted_text != null) {
                const keep_streaming = try self.emitDecodedDelta(
                    token_ids[prompt_token_count..seq_len.*],
                    emitted_text.?,
                    on_token_fn.?,
                    on_token_ctx.?,
                );
                if (!keep_streaming) {
                    _ = pending.awaitToken() catch {};
                    finish_reason.* = "stop";
                    return true;
                }
            }
            if (!stepped) {
                if (tokens_generated.* >= max_tokens) break;
                const rearmed = try pending.arm(token_ids[seq_len.* - 1], seq_len.*);
                if (!rearmed) return true;
            }
        }
        return true;
    }

    fn standardDecodeCudaPendingTokenReadback(
        self: *NativeGenerationPipeline,
        token_ids: []i64,
        seq_len: *usize,
        decode_state: *NativeDecodeState,
        config: GenerationConfig,
        prefill_last_logits: *?[]f32,
        prefill_greedy_token: *?usize,
        penalty_state: *SamplingPenaltyState,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*grammar_mod.GbnfGrammar,
        max_tokens: usize,
        prompt_token_count: usize,
        on_token_fn: ?TokenCallback,
        on_token_ctx: ?*anyopaque,
        emitted_text: ?*StreamingTextState,
        work_trace: bool,
    ) !?DecodeResult {
        if (!enableCudaGreedyPendingTokenReadback()) return null;
        if (self.cb.kind() != .cuda) return null;
        if (self.graph_cache != null or self.compiled_partition_backend != null) return null;
        if (!pendingTokenReadbackStreamingArgsValid(on_token_fn, on_token_ctx, emitted_text)) return null;
        if (!isPureGreedyConfig(config)) return null;
        if (token_table != null or json_grammar.* != null or gbnf_grammar != null) return null;
        if (max_tokens < 2) return null;

        const allocator = self.allocator;
        var decode_runtime = BorrowedDecodeStateRuntime.init(decode_state);
        if (decode_runtime.kvView() == null) return null;
        const phase_timer = @import("antfly_readers").pipeline_metrics.start(.decode);
        defer phase_timer.finish();

        var tokens_generated: usize = 0;
        var finish_reason: []const u8 = "length";
        var input_token = self.deviceTokenOwner();
        var candidate_token = self.deviceTokenOwner();
        defer input_token.clear();
        defer candidate_token.clear();

        debugGenerationStage(
            "standardDecode pending-token-readback enter seq_len={d} max_tokens={d}",
            .{ seq_len.*, max_tokens },
        );

        while (tokens_generated < max_tokens) {
            if (self.execution_control) |control| try control.update(.executing, @intCast(tokens_generated), @intCast(max_tokens));
            if (candidate_token.tensor == null) {
                if (tokens_generated == 0) {
                    if (prefill_greedy_token.*) |token| {
                        prefill_greedy_token.* = null;
                        if (self.shouldStopOnEos(config, token, work_trace)) {
                            finish_reason = "stop";
                            break;
                        }
                        if (self.shouldSeedDeviceTokenHandoff(tokens_generated, decode_state, config, token_table, json_grammar, gbnf_grammar)) {
                            try input_token.seed(token);
                            decoder_runtime_debug_stats.device_token_handoff_seeds += 1;
                        }
                        token_ids[seq_len.*] = @intCast(token);
                        seq_len.* += 1;
                        tokens_generated += 1;
                        _ = try decode_runtime.appendGeneratedToken();
                        try penalty_state.noteToken(allocator, @intCast(token));
                        self.noteDecodeProgressNoMicrobatch(tokens_generated);
                        if (!try self.emitCudaPendingTokenReadbackDelta(
                            token_ids,
                            seq_len.*,
                            prompt_token_count,
                            on_token_fn,
                            on_token_ctx,
                            emitted_text,
                        )) {
                            finish_reason = "stop";
                            break;
                        }
                        continue;
                    }
                    if (prefill_last_logits.*) |cached| {
                        const outcome = try self.sampleNextToken(
                            cached,
                            config,
                            penalty_state,
                            token_table,
                            json_grammar,
                            gbnf_grammar,
                        );
                        const token = outcome.token;
                        if (self.shouldStopOnEos(config, token, work_trace)) {
                            finish_reason = "stop";
                            break;
                        }
                        if (self.shouldSeedDeviceTokenHandoff(tokens_generated, decode_state, config, token_table, json_grammar, gbnf_grammar)) {
                            try input_token.seed(token);
                            decoder_runtime_debug_stats.device_token_handoff_seeds += 1;
                        }
                        token_ids[seq_len.*] = @intCast(token);
                        seq_len.* += 1;
                        tokens_generated += 1;
                        _ = try decode_runtime.appendGeneratedToken();
                        try penalty_state.noteToken(allocator, @intCast(token));
                        self.noteDecodeProgressNoMicrobatch(tokens_generated);
                        if (!try self.emitCudaPendingTokenReadbackDelta(
                            token_ids,
                            seq_len.*,
                            prompt_token_count,
                            on_token_fn,
                            on_token_ctx,
                            emitted_text,
                        )) {
                            finish_reason = "stop";
                            break;
                        }
                        if (outcome.grammar_complete) {
                            finish_reason = "stop";
                            break;
                        }
                        continue;
                    }
                }

                if (input_token.tensor) |input_tensor| {
                    var numerical = self.physicalDecoder();
                    var candidate_events = decoder_forward.PendingCandidateEvents{};
                    const candidate = numerical.pendingCandidate(decode_state, .{
                        .token_ids = token_ids,
                        .sequence_length = seq_len.*,
                        .generated_tokens = tokens_generated,
                        .input_token_tensor = input_tensor,
                        .pure_greedy = isPureGreedyConfig(config),
                        .grammar_active = token_table != null or json_grammar.* != null or gbnf_grammar != null,
                        .prefetch_drain_budget = prefetch_drain_budget_per_step,
                    }, &candidate_events) catch |err| {
                        notePendingCandidateEvents(work_trace, @intFromPtr(self), seq_len.*, false, candidate_events);
                        return err;
                    };
                    notePendingCandidateEvents(work_trace, @intFromPtr(self), seq_len.*, false, candidate_events);
                    if (candidate == .tensor) {
                        candidate_token.replace(candidate.tensor);
                        input_token.clear();
                        continue;
                    }
                    if (candidate == .scalar) {
                        const resolved = candidate.scalar;
                        var next_token = self.deviceTokenOwner();
                        next_token.replace(resolved.token_tensor);
                        defer next_token.clear();
                        if (self.shouldStopOnEos(config, resolved.token, work_trace)) {
                            finish_reason = "stop";
                            break;
                        }
                        if (next_token.tensor == null and self.shouldSeedDeviceTokenHandoff(tokens_generated, decode_state, config, token_table, json_grammar, gbnf_grammar)) {
                            try next_token.seed(resolved.token);
                            decoder_runtime_debug_stats.device_token_handoff_seeds += 1;
                        }
                        input_token.replace(next_token.take());
                        token_ids[seq_len.*] = @intCast(resolved.token);
                        seq_len.* += 1;
                        tokens_generated += 1;
                        _ = try decode_runtime.appendGeneratedToken();
                        try penalty_state.noteToken(allocator, @intCast(resolved.token));
                        self.noteDecodeProgressNoMicrobatch(tokens_generated);
                        if (!try self.emitCudaPendingTokenReadbackDelta(
                            token_ids,
                            seq_len.*,
                            prompt_token_count,
                            on_token_fn,
                            on_token_ctx,
                            emitted_text,
                        )) {
                            finish_reason = "stop";
                            break;
                        }
                        continue;
                    }
                }

                break;
            }

            const candidate = candidate_token.tensor.?;
            if (tokens_generated + 1 >= max_tokens) {
                const token = try candidate_token.resolve(allocator);
                if (self.shouldStopOnEos(config, token, work_trace)) {
                    finish_reason = "stop";
                    break;
                }
                token_ids[seq_len.*] = @intCast(token);
                seq_len.* += 1;
                tokens_generated += 1;
                _ = try decode_runtime.appendGeneratedToken();
                try penalty_state.noteToken(allocator, @intCast(token));
                self.noteDecodeProgressNoMicrobatch(tokens_generated);
                if (!try self.emitCudaPendingTokenReadbackDelta(
                    token_ids,
                    seq_len.*,
                    prompt_token_count,
                    on_token_fn,
                    on_token_ctx,
                    emitted_text,
                )) {
                    finish_reason = "stop";
                    break;
                }
                input_token.replace(candidate_token.take());
                continue;
            }

            var pending = (try pending_step.Readback.begin(self.pendingStepContext(decode_state), candidate)) orelse {
                const token = try candidate_token.resolve(allocator);
                if (self.shouldStopOnEos(config, token, work_trace)) {
                    finish_reason = "stop";
                    break;
                }
                token_ids[seq_len.*] = @intCast(token);
                seq_len.* += 1;
                tokens_generated += 1;
                _ = try decode_runtime.appendGeneratedToken();
                try penalty_state.noteToken(allocator, @intCast(token));
                self.noteDecodeProgressNoMicrobatch(tokens_generated);
                if (!try self.emitCudaPendingTokenReadbackDelta(
                    token_ids,
                    seq_len.*,
                    prompt_token_count,
                    on_token_fn,
                    on_token_ctx,
                    emitted_text,
                )) {
                    finish_reason = "stop";
                    break;
                }
                input_token.replace(candidate_token.take());
                continue;
            };
            defer pending.deinit();

            // The current token remains resident for the following graph, but
            // its readback must establish continuation before any future KV
            // write. Otherwise EOS launches one whole unused decode step and
            // request retirement waits for it inside the first device free.
            const token = try pending.resolve();
            if (self.shouldStopOnEos(config, token, work_trace)) {
                candidate_token.clear();
                finish_reason = "stop";
                break;
            }

            token_ids[seq_len.*] = @intCast(token);
            seq_len.* += 1;
            var uncommitted_cursor = true;
            errdefer if (uncommitted_cursor) {
                seq_len.* -= 1;
            };
            _ = try pending.reservePosition();
            var lookahead_runtime = self.physicalDecoder();
            var lookahead_events = decoder_forward.PendingCandidateEvents{};
            const lookahead = lookahead_runtime.pendingTensorCandidate(decode_state, .{
                .token_ids = token_ids,
                .sequence_length = seq_len.*,
                .generated_tokens = tokens_generated + 1,
                .input_token_tensor = candidate,
                .pure_greedy = isPureGreedyConfig(config),
                .grammar_active = token_table != null or json_grammar.* != null or gbnf_grammar != null,
                .prefetch_drain_budget = prefetch_drain_budget_per_step,
            }, &lookahead_events) catch |err| {
                notePendingCandidateEvents(work_trace, @intFromPtr(self), seq_len.*, true, lookahead_events);
                return err;
            };
            notePendingCandidateEvents(work_trace, @intFromPtr(self), seq_len.*, true, lookahead_events);
            if (lookahead) |next| {
                try pending.retainLookahead(next);
            }

            try pending.commit();
            uncommitted_cursor = false;
            tokens_generated += 1;
            try penalty_state.noteToken(allocator, @intCast(token));
            self.noteDecodeProgressNoMicrobatch(tokens_generated);

            if (!try self.emitCudaPendingTokenReadbackDelta(
                token_ids,
                seq_len.*,
                prompt_token_count,
                on_token_fn,
                on_token_ctx,
                emitted_text,
            )) {
                pending.discardLookahead();
                candidate_token.clear();
                finish_reason = "stop";
                break;
            }

            if (pending.takeLookahead()) |next| {
                candidate_token.replace(next);
            } else {
                input_token.replace(candidate_token.take());
            }
        }

        debugGenerationStage(
            "standardDecode pending-token-readback exit tokens_generated={d} finish_reason={s}",
            .{ tokens_generated, finish_reason },
        );
        return .{ .tokens_generated = tokens_generated, .finish_reason = finish_reason };
    }

    fn emitCudaPendingTokenReadbackDelta(
        self: *NativeGenerationPipeline,
        token_ids: []const i64,
        seq_len: usize,
        prompt_token_count: usize,
        on_token_fn: ?TokenCallback,
        on_token_ctx: ?*anyopaque,
        emitted_text: ?*StreamingTextState,
    ) !bool {
        if (on_token_fn) |callback| {
            return self.emitDecodedDelta(
                token_ids[prompt_token_count..seq_len],
                emitted_text.?,
                callback,
                on_token_ctx.?,
            );
        }
        return true;
    }

    fn forwardGreedyDeviceDecodeToken(
        self: *NativeGenerationPipeline,
        token_ids: []const i64,
        seq_len: usize,
        tokens_generated: usize,
        decode_state: *NativeDecodeState,
        config: GenerationConfig,
        penalty_state: *const SamplingPenaltyState,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *const ?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*const grammar_mod.GbnfGrammar,
        input_token_tensor: ?ops.CT,
    ) !?DeviceDecodeOutcome {
        if (!requestSuppressionsAllowResidentGreedy(config.effectiveSuppressTokenIds(&self.gpt_config))) return null;
        decoder_runtime_debug_stats.forward_attempts += 1;
        var numerical = self.physicalDecoder();
        if (!noteDeviceRoute(numerical.deviceRoute(decode_state, .{
            .mode = .scalar,
            .generated_tokens = tokens_generated,
            .pure_greedy = isPureGreedyConfig(config),
            .grammar_active = token_table != null or json_grammar.* != null or gbnf_grammar != null,
        }))) return null;
        const sampled = !isPureGreedyConfig(config);
        var events = decoder_forward.DeviceStepEvents{};
        defer noteDeviceStepEvents(events);
        const outcome = try numerical.forwardDeviceStep(decode_state, .{
            .token_ids = token_ids,
            .sequence_length = seq_len,
            .input_token_tensor = input_token_tensor,
            .sampling = if (sampled) .{
                .temperature = config.temperature,
                .top_p = config.top_p,
                .top_k = config.top_k,
                .min_p = config.min_p,
                .repetition_penalty = config.repetition_penalty,
                .frequency_penalty = config.frequency_penalty,
                .presence_penalty = config.presence_penalty,
            } else null,
            .prefetch_drain_budget = prefetch_drain_budget_per_step,
        }, &events);
        return switch (outcome) {
            .token => |token| token,
            .declined => blk: {
                if (sampled) decoder_runtime_debug_stats.non_greedy += 1;
                break :blk null;
            },
            .logits => |logits| blk: {
                defer self.allocator.free(logits);
                // Task penalties/model suppression stay on the canonical
                // sampler when the numerical frame cannot select a token.
                var no_json_grammar: ?grammar_mod.JsonGrammar = null;
                const selected = try self.sampleNextToken(logits, config, penalty_state, null, &no_json_grammar, null);
                break :blk .{ .token = selected.token };
            },
        };
    }

    fn notePendingCandidateEvents(work_trace: bool, pipeline: usize, sequence_length: usize, lookahead: bool, events: decoder_forward.PendingCandidateEvents) void {
        if (work_trace) std.debug.print("native_work_pending_candidate: pipeline={d} sequence_length={d} lookahead={} attempts={d} tensor_route={any} scalar_route={any} handoff_attempts={d} handoff_hits={d} handoff_fallbacks={d}\n", .{ pipeline, sequence_length, lookahead, events.attempts, events.tensor_route, events.scalar_route, events.handoff.handoff_attempts, events.handoff.handoff_hits, events.handoff.handoff_fallbacks });
        decoder_runtime_debug_stats.forward_attempts += events.attempts;
        if (events.tensor_route) |route| _ = noteDeviceRoute(route);
        if (events.scalar_route) |route| _ = noteDeviceRoute(route);
        noteDeviceStepEvents(events.handoff);
    }

    fn noteDeviceStepEvents(events: decoder_forward.DeviceStepEvents) void {
        decoder_runtime_debug_stats.device_token_handoff_attempts += events.handoff_attempts;
        decoder_runtime_debug_stats.device_token_handoff_hits += events.handoff_hits;
        decoder_runtime_debug_stats.device_token_handoff_fallbacks += events.handoff_fallbacks;
    }

    fn shouldSeedDeviceTokenHandoff(
        self: *NativeGenerationPipeline,
        tokens_generated: usize,
        decode_state: *NativeDecodeState,
        config: GenerationConfig,
        token_table: ?*const grammar_mod.TokenByteTable,
        json_grammar: *const ?grammar_mod.JsonGrammar,
        gbnf_grammar: ?*const grammar_mod.GbnfGrammar,
    ) bool {
        if (!requestSuppressionsAllowResidentGreedy(config.effectiveSuppressTokenIds(&self.gpt_config))) return false;
        const numerical = self.physicalDecoder();
        return numerical.deviceRoute(decode_state, .{
            .mode = .seed,
            .generated_tokens = tokens_generated,
            .pure_greedy = isPureGreedyConfig(config),
            .grammar_active = token_table != null or json_grammar.* != null or gbnf_grammar != null,
        }) == .eligible;
    }

    fn noteDeviceRoute(route: decoder_forward.DeviceRoute) bool {
        switch (route) {
            .eligible => return true,
            .backend_not_device => decoder_runtime_debug_stats.backend_not_device_decode += 1,
            .graph_blocked => decoder_runtime_debug_stats.graph_blocked += 1,
            .first_token_blocked => decoder_runtime_debug_stats.first_token_blocked += 1,
            .kv_missing => decoder_runtime_debug_stats.kv_missing += 1,
            .non_greedy => decoder_runtime_debug_stats.non_greedy += 1,
            .grammar_blocked => decoder_runtime_debug_stats.grammar_blocked += 1,
            .handoff_disabled => {},
        }
        return false;
    }

    fn deviceTokenOwner(self: *NativeGenerationPipeline) decoder_forward.DeviceToken {
        return .{ .backend = &self.cb, .access = if (self.execution_lock) |mutex| self.executionAccess(mutex) else null };
    }

    fn decodeBudgetAllowsPipelineRearm(generated: usize, max_tokens: usize) bool {
        return generated < max_tokens and max_tokens - generated > 1;
    }

    fn compiledMetalRuntimePrepareRequired(
        bounded_ple_enabled: bool,
        bounded_ple_disabled: bool,
        has_e2b_mirror_admission: bool,
        matching_mirror_requested: bool,
    ) bool {
        return (bounded_ple_enabled and !bounded_ple_disabled) or
            (has_e2b_mirror_admission and matching_mirror_requested);
    }

    fn prepareCompiledGenerationRuntime(
        self: *NativeGenerationPipeline,
        kv_tokens_hint: usize,
    ) !bool {
        self.compiled_runtime_prepare_after_reset = false;
        self.compiled_runtime_prepare_token_hint = 0;
        self.bounded_ple_prefill_decode_handoff_required = false;
        const cache = self.graph_cache orelse return false;
        try self.rejectUnsupportedDeepSeekV4GraphMode();
        if (self.compiled_partition_backend == null or self.compiled_attachment_target != .whole_model) return false;
        // Ordinary Metal graph execution prepares lazily. Request-scoped
        // bounded PLE and mirror admission are different: prepare() owns their
        // typed policy handoff and must run before the first prefill chunk.
        if (self.compiled_partition_backend == .metal) {
            const bounded_ple_required = (try boundedPleQ6RequestScratchBytes(
                .metal,
                self.gpt_config,
                platform.env.getenvBool("TERMITE_METAL_ENABLE_BOUNDED_PLE_Q6_ROWS"),
                platform.env.getenvBool("TERMITE_METAL_DISABLE_BOUNDED_PLE_Q6_ROWS"),
            )) != 0;
            const required = compiledMetalRuntimePrepareRequired(
                bounded_ple_required,
                false,
                self.e2b_f16_mirror_admission != null,
                gemmaF16MirrorPrepareRequested(self.gpt_config, self.e2b_f16_mirror_admission != null),
            );
            self.compiled_runtime_prepare_after_reset = required;
            self.compiled_runtime_prepare_token_hint = kv_tokens_hint;
            self.bounded_ple_prefill_decode_handoff_required = required and
                self.e2b_f16_mirror_admission != null and
                try boundedPleF16MirrorPhaseRequested(.metal, self.gpt_config);
            if (!required) return false;
            if (!try graph_mod.execution.prepareCompiledModelRuntime(&self.graphExecutionContext(), cache, kv_tokens_hint))
                return error.RequiredCompiledRuntimePrepareDeclined;
            return true;
        }
        var decoder = self.physicalDecoder();
        return decoder.prepareCompiledGenerationRuntime(kv_tokens_hint);
    }

    fn forwardAllLogits(self: *NativeGenerationPipeline, input_ids: []const i64, batch: usize, seq_len: usize, decode_context: *const gpt_arch.DecodeContext) ![]f32 {
        return graph_mod.decoder_step_executor.forwardAll(&self.graphExecutionContext(), self.graph_cache, input_ids, batch, seq_len, decode_context, &decoder_runtime_debug_stats.replay_last_logits_fallbacks);
    }

