    try model.putWeight(allocator, "model.norm.weight", &.{4}, &.{ 1.0, 1.0, 1.0, 1.0 });
    try model.putWeight(allocator, "lm_head.weight", &.{ 6, 4 }, &.{
        1.0, 0.0, 0.0, 0.0,
